import { AppData } from '../types';

const getStorageKey = (hotel: string, dept: string, year: number, month: number) => {
  return `asistencia_${hotel.replace(/\s/g, '_')}_${dept.replace(/\s/g, '_')}_${year}_${month}`;
};

export const saveToStorage = (data: AppData) => {
  const key = getStorageKey(data.metadata.hotel, data.metadata.departamento, data.metadata.año, data.metadata.mes);
  data.metadata.ultimaModificacion = new Date().toISOString();
  localStorage.setItem(key, JSON.stringify(data));
};

export const loadFromStorage = (hotel: string, dept: string, year: number, month: number): AppData | null => {
  const key = getStorageKey(hotel, dept, year, month);
  const data = localStorage.getItem(key);
  return data ? JSON.parse(data) : null;
};

import { GoogleGenAI, Modality } from "@google/genai";

const apiKey = process.env.API_KEY || "";
const ai = new GoogleGenAI({ apiKey });

export const generateSpeechSummary = async (textToSay: string): Promise<string | null> => {
  if (!apiKey) {
    console.error("API Key not found");
    return null;
  }

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text: textToSay }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: 'Kore' },
          },
        },
      },
    });

    const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
    if (base64Audio) {
      return base64Audio;
    }
    return null;

  } catch (error) {
    console.error("Error generating speech:", error);
    return null;
  }
};

export const decodeAndPlayAudio = async (base64Audio: string) => {
  try {
    const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
    const audioString = atob(base64Audio);
    const len = audioString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
        bytes[i] = audioString.charCodeAt(i);
    }
    const audioBuffer = await audioContext.decodeAudioData(bytes.buffer);
    const source = audioContext.createBufferSource();
    source.buffer = audioBuffer;
    source.connect(audioContext.destination);
    source.start(0);
  } catch (e) {
    console.error("Error playing audio", e);
  }
}

