import React, { useState, useEffect } from 'react';
import SelectionScreen from './components/SelectionScreen';
import QuadrantScreen from './components/QuadrantScreen';
import ManualModal from './components/ManualModal';
import { AppData } from './types';
import { INITIAL_EMPLOYEES_MOCK } from './constants';
import { loadFromStorage } from './services/storageService';

const App: React.FC = () => {
  const [currentScreen, setCurrentScreen] = useState<'selection' | 'quadrant'>('selection');
  const [appData, setAppData] = useState<AppData | null>(null);
  const [showManual, setShowManual] = useState(false);

  const handleStart = (hotel: string, dept: string, year: number, month: number) => {
    // Try load existing
    const existing = loadFromStorage(hotel, dept, year, month);

    if (existing) {
      setAppData(existing);
    } else {
      // Create new
      const newData: AppData = {
        metadata: {
          hotel,
          departamento: dept,
          año: year,
          mes: month,
          ultimaModificacion: new Date().toISOString()
        },
        empleados: INITIAL_EMPLOYEES_MOCK // For testing as requested
      };
      setAppData(newData);
    }
    setCurrentScreen('quadrant');
  };

  const handleBack = () => {
    setCurrentScreen('selection');
    setAppData(null);
  };

  return (
    <>
      {currentScreen === 'selection' && (
        <SelectionScreen onStart={handleStart} onOpenManual={() => setShowManual(true)} />
      )}

      {currentScreen === 'quadrant' && appData && (
        <QuadrantScreen 
          data={appData} 
          onBack={handleBack} 
          onUpdateData={setAppData}
        />
      )}

      <ManualModal isOpen={showManual} onClose={() => setShowManual(false)} />
    </>
  );
};

