import * as XLSX from 'xlsx';
import { AppData, Employee } from '../types';
import { CODES, MONTHS } from '../constants';

export const generateExcelReport = (data: AppData, employees: Employee[]) => {
  const { hotel, departamento, año, mes } = data.metadata;
  const daysInMonth = new Date(año, mes, 0).getDate();
  const monthName = MONTHS[mes - 1];

  // --- HOJA 1: CUADRANTE ---

  // 1. Títulos y Metadatos
  const wsData: any[][] = [
    [`CONTROL DE ASISTENCIA - ${hotel.toUpperCase()}`],
    [`Departamento: ${departamento} | Período: ${monthName} ${año}`],
    [], // Espacio en blanco
  ];

  // 2. Encabezados de la tabla (Empleado + Días 1-31)
  const headers = ['Empleado'];
  for (let i = 1; i <= daysInMonth; i++) {
    headers.push(String(i));
  }
  wsData.push(headers);

  // 3. Filas de Empleados
  employees.forEach(emp => {
    const row: any[] = [emp.nombre];

    // Verificar estado SC (Sin Contrato) para exportación
    const alta = new Date(emp.fechaAlta);
    const baja = emp.fechaBaja ? new Date(emp.fechaBaja) : null;

    for (let d = 1; d <= daysInMonth; d++) {
      const dateCheck = new Date(año, mes - 1, d);
      let cellValue = emp.asistencia[String(d)] || '';

      // Lógica SC básica para el reporte
      if (dateCheck < alta) {
        cellValue = 'SC';
      } else if (baja && dateCheck > baja) {
        cellValue = 'SC';
      }

      row.push(cellValue);
    }
    wsData.push(row);
  });

  // 4. Fila de Ratios
  const ratioRow: any[] = ['RATIO PERSONAL'];
  for (let d = 1; d <= daysInMonth; d++) {
    let total = 0;
    employees.forEach(emp => {
      // Replicar lógica de cálculo de ratio básica
      // (Nota: Para un reporte exacto, idealmente compartiríamos la función lógica, 
      // pero aquí simplificamos asumiendo que el estado 'SC' ya se filtró o se calcula igual)

      const alta = new Date(emp.fechaAlta);
      const baja = emp.fechaBaja ? new Date(emp.fechaBaja) : null;
      const dateCheck = new Date(año, mes - 1, d);

      let status = emp.asistencia[String(d)];

      // Si es SC, ignorar
      if (dateCheck < alta || (baja && dateCheck > baja)) return;

      const code = CODES.find(c => c.code === status);
      if (code) {
        total += code.ratio;
      }
    });
    ratioRow.push(total % 1 === 0 ? total : total.toFixed(1));
  }
  wsData.push(ratioRow);

  // Crear Hoja de Trabajo
  const ws = XLSX.utils.aoa_to_sheet(wsData);

  // Ajustar anchos de columna básicos
  const wscols = [{ wch: 30 }]; // Primera columna (nombres) más ancha
  for (let i = 1; i <= daysInMonth; i++) wscols.push({ wch: 4 }); // Columnas de días estrechas
  ws['!cols'] = wscols;

  // --- HOJA 2: LEYENDA ---
  const legendData = [
    ['CÓDIGO', 'DESCRIPCIÓN', 'RATIO', 'TECLA'],
    ...CODES.map(c => [c.code, c.name, c.ratio, c.key.toUpperCase()]),
    ['SC', 'Sin Contrato', 0, '-']
  ];
  const wsLegend = XLSX.utils.aoa_to_sheet(legendData);
  const wsLegendCols = [{ wch: 10 }, { wch: 30 }, { wch: 10 }, { wch: 10 }];
  wsLegend['!cols'] = wsLegendCols;

  // --- CREAR LIBRO Y DESCARGAR ---
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, "Cuadrante");
  XLSX.utils.book_append_sheet(wb, wsLegend, "Leyenda");

  const fileName = `Informe_${hotel.replace(/\s/g, '')}_${departamento}_${monthName}_${año}.xlsx`;
  XLSX.writeFile(wb, fileName);
};

