import React, { useRef, useState, useEffect } from 'react';
import { Employee, SelectionState } from '../types';
import { CODES, SC_CODE } from '../constants';
import { isAfter, isBefore, parseISO } from 'date-fns';

interface AttendanceGridProps {
  year: number;
  month: number;
  employees: Employee[];
  selection: SelectionState;
  setSelection: React.Dispatch<React.SetStateAction<SelectionState>>;
  onCellClick: (empId: string, day: number, ctrlKey: boolean, shiftKey: boolean) => void;
  onEditEmployee: (id: string) => void;
}

const AttendanceGrid: React.FC<AttendanceGridProps> = ({ 
  year, 
  month, 
  employees, 
  selection, 
  setSelection, 
  onCellClick,
  onEditEmployee
}) => {
  const daysInMonth = new Date(year, month, 0).getDate();
  const days = Array.from({ length: daysInMonth }, (_, i) => i + 1);
  const weekDays = ['D', 'L', 'M', 'X', 'J', 'V', 'S']; // 0 = Sunday

  const isMouseDown = useRef(false);

  // Helper to determine if a cell is "SC" (Sin Contrato)
  const getCellStatus = (emp: Employee, day: number) => {
    // Construct date string YYYY-MM-DD
    const dateStr = `${year}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
    const currentDate = new Date(dateStr);
    const alta = new Date(emp.fechaAlta);

    if (currentDate < alta) return 'SC';

    if (emp.fechaBaja) {
      const baja = new Date(emp.fechaBaja);
      if (currentDate > baja) return 'SC';
    }

    return emp.asistencia[String(day)] || '';
  };

  // Helper to check if trial period applies to this specific day
  const isTrialDay = (emp: Employee, day: number) => {
    if (!emp.periodoPrueba.activo || !emp.periodoPrueba.fechaFin) return false;
    const dateStr = `${year}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
    return dateStr <= emp.periodoPrueba.fechaFin && dateStr >= emp.fechaAlta;
  };

  const getDayOfWeek = (day: number) => {
    const date = new Date(year, month - 1, day);
    return date.getDay();
  };

  const getCodeStyle = (codeStr: string) => {
    if (codeStr === 'SC') return { bg: SC_CODE.bgColor, text: SC_CODE.textColor };
    const found = CODES.find(c => c.code === codeStr);
    return found ? { bg: found.bgColor, text: found.textColor } : { bg: 'white', text: 'black' };
  };

  const handleMouseDown = (empId: string, day: number, e: React.MouseEvent) => {
    if (getCellStatus(employees.find(em => em.id === empId)!, day) === 'SC') return;
    isMouseDown.current = true;
    onCellClick(empId, day, e.ctrlKey, e.shiftKey);
  };

  const handleMouseEnter = (empId: string, day: number) => {
    if (isMouseDown.current) {
      onCellClick(empId, day, false, true); // Treat drag as Shift+Click (range)
    }
  };

  const handleMouseUp = () => {
    isMouseDown.current = false;
  };

  // Ratio Calculation
  const calculateRatio = (day: number) => {
    let total = 0;
    employees.forEach(emp => {
      const status = getCellStatus(emp, day);
      if (status === 'SC') return;

      const code = CODES.find(c => c.code === status);
      if (code) {
        total += code.ratio;
      }
    });
    return total % 1 === 0 ? total : total.toFixed(1);
  };

  useEffect(() => {
    window.addEventListener('mouseup', handleMouseUp);
    return () => window.removeEventListener('mouseup', handleMouseUp);
  }, []);

  return (
    <div className="flex flex-col h-full bg-white select-none">
      <div className="flex-1 overflow-auto relative">
        <table className="border-collapse w-full min-w-max">
          <thead className="sticky top-0 z-40 bg-gray-100 shadow-sm">
            <tr>
              <th className="sticky left-0 z-50 bg-gray-50 p-2 border border-gray-300 w-[200px] min-w-[200px] text-left text-sm font-bold text-gray-700">
                Empleado
              </th>
              {days.map(d => {
                const dow = getDayOfWeek(d);
                const isWeekend = dow === 0 || dow === 6;
                const bgHeader = dow === 6 ? 'bg-blue-50' : dow === 0 ? 'bg-blue-100' : 'bg-white';
                return (
                  <th key={d} className={`border border-gray-300 w-[45px] min-w-[45px] text-center ${bgHeader}`}>
                    <div className="text-xs font-bold text-gray-800">{d}</div>
                    <div className={`text-[10px] font-medium ${isWeekend ? 'text-blue-800' : 'text-gray-500'}`}>
                      {weekDays[dow]}
                    </div>
                  </th>
                );
              })}
            </tr>
          </thead>
          <tbody>
            {employees.map(emp => (
              <tr key={emp.id} className="hover:bg-gray-50">
                <td className="sticky left-0 z-30 bg-white p-2 border border-gray-300 w-[200px] text-sm font-medium text-gray-800 truncate border-r-2 border-r-gray-300 cursor-pointer hover:bg-gray-100"
                    onClick={() => onEditEmployee(emp.id)}
                    title="Click para editar"
                >
                  <div className="flex items-center gap-2">
                    {emp.periodoPrueba.activo && <span title="Periodo de Prueba Activo">⏱️</span>}
                    <span className="truncate">{emp.nombre}</span>
                  </div>
                </td>
                {days.map(d => {
                  const status = getCellStatus(emp, d);
                  const isSC = status === 'SC';
                  const style = getCodeStyle(status);
                  const isSelected = selection.selectedCells.has(`${emp.id}_${d}`);
                  const isTrial = isTrialDay(emp, d);

                  return (
                    <td
                      key={d}
                      onMouseDown={(e) => handleMouseDown(emp.id, d, e)}
                      onMouseEnter={() => handleMouseEnter(emp.id, d)}
                      className={`
                        border border-gray-200 text-center text-xs font-bold cursor-default transition-all duration-75
                        ${isSC ? 'cursor-not-allowed opacity-80' : 'cursor-pointer'}
                        ${isSelected ? 'ring-2 ring-blue-600 z-20 relative' : ''}
                        ${!isSC && isTrial ? 'border-b-4 border-b-orange-400' : ''}
                      `}
                      style={{ 
                        backgroundColor: style.bg, 
                        color: style.text,
                        height: '35px'
                      }}
                    >
                      {isSC ? '' : status}
                    </td>
                  );
                })}
              </tr>
            ))}
            {/* RATIO ROW */}
            <tr className="sticky bottom-0 z-40">
              <td className="sticky left-0 z-50 bg-gray-800 text-white p-2 border border-gray-700 font-bold text-sm text-right pr-4">
                RATIO PERSONAL
              </td>
              {days.map(d => (
                <td key={d} className="bg-gray-800 text-white border border-gray-700 text-center text-xs font-bold h-[35px]">
                  {calculateRatio(d)}
                </td>
              ))}
            </tr>
          </tbody>
        </table>
      </div>
    </div>
  );
};

