import React, { useState, useEffect, useCallback, useRef, useMemo } from 'react';
import { AppData, Employee, SelectionState } from '../types';
import { CODES, MONTHS } from '../constants';
import AttendanceGrid from './AttendanceGrid';
import Toolbar from './Toolbar';
import EmployeeModal from './EmployeeModal';
import ManualModal from './ManualModal';
import { saveToStorage, syncEmployeeAcrossMonths, deleteEmployeeAcrossMonths } from '../services/storageService';
import { generateExcelReport, generatePDFReport } from '../services/reportService';

interface QuadrantScreenProps {
  data: AppData;
  onBack: () => void;
  onUpdateData: (newData: AppData) => void;
}

const QuadrantScreen: React.FC<QuadrantScreenProps> = ({ data, onBack, onUpdateData }) => {
  const [employees, setEmployees] = useState<Employee[]>(data.empleados);
  const [selection, setSelection] = useState<SelectionState>({ start: null, current: null, selectedCells: new Set() });
  const [showEmpModal, setShowEmpModal] = useState(false);
  const [editingEmpId, setEditingEmpId] = useState<string | null>(null);
  const [showManual, setShowManual] = useState(false);
  const [showLegend, setShowLegend] = useState(true);
  const [saveStatus, setSaveStatus] = useState<'saved' | 'saving' | null>(null);
  const [showDownloadMenu, setShowDownloadMenu] = useState(false);
  const downloadMenuRef = useRef<HTMLDivElement>(null);

  // --- Locking Logic ---
  const isMonthLocked = useMemo(() => {
    const { año, mes } = data.metadata;
    // Get last day of the current quadrant month
    // Date(year, monthIndex, 0) gives last day of previous month index. 
    // data.metadata.mes is 1-based (1=Jan). JS Date month is 0-based.
    // We want last day of "mes". 
    // Example: mes=1 (Jan). new Date(2025, 1, 0) -> Day 0 of Feb 2025 -> Jan 31, 2025. Correct.
    const lastDayOfMonth = new Date(año, mes, 0); 

    // Lock date is 7 days after the end of the month
    const lockDate = new Date(lastDayOfMonth);
    lockDate.setDate(lockDate.getDate() + 7);
    lockDate.setHours(23, 59, 59, 999); // End of that day

    return new Date() > lockDate;
  }, [data.metadata.año, data.metadata.mes]);

  // --- Persistence & Auto-Sync ---
  useEffect(() => {
    // Save current month specifically
    const newData = { ...data, empleados: employees };

    // Optimistic UI update
    setSaveStatus('saving');

    // Simulate server request time (small delay)
    const timeout = setTimeout(() => {
        saveToStorage(newData);
        setSaveStatus('saved');
        setTimeout(() => setSaveStatus(null), 2000);
    }, 500);

    onUpdateData(newData); // Update parent state

    return () => clearTimeout(timeout);
  }, [employees]);

  // Click outside to close download menu
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (downloadMenuRef.current && !downloadMenuRef.current.contains(event.target as Node)) {
        setShowDownloadMenu(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // --- Handlers ---

  const handleApplyCode = (code: string) => {
    if (isMonthLocked) return;
    if (selection.selectedCells.size === 0) return;

    setEmployees(prev => prev.map(emp => {
      const newAsistencia = { ...emp.asistencia };
      let modified = false;

      // Iterate 1-31
      for (let d = 1; d <= 31; d++) {
        const key = `${emp.id}_${d}`;
        if (selection.selectedCells.has(key)) {
           newAsistencia[String(d)] = code;
           modified = true;
        }
      }
      return modified ? { ...emp, asistencia: newAsistencia } : emp;
    }));
  };

  const handleKeydown = useCallback((e: KeyboardEvent) => {
    if (showEmpModal || showManual || (e.target as HTMLElement).tagName === 'INPUT') return;
    if (isMonthLocked) return;

    const key = e.key.toLowerCase();
    const found = CODES.find(c => c.key === key);
    if (found) {
      handleApplyCode(found.code);
      e.preventDefault();
    }
  }, [selection, showEmpModal, showManual, isMonthLocked]);

  useEffect(() => {
    window.addEventListener('keydown', handleKeydown);
    return () => window.removeEventListener('keydown', handleKeydown);
  }, [handleKeydown]);

  // --- Selection Logic ---

  const handleCellClick = (empId: string, day: number, ctrlKey: boolean, shiftKey: boolean) => {
    if (isMonthLocked) return; // Disable selection if locked

    const key = `${empId}_${day}`;

    setSelection(prev => {
      const newSet = new Set(ctrlKey ? prev.selectedCells : (shiftKey ? prev.selectedCells : []));

      if (shiftKey && prev.start) {
        const startEmpIdx = employees.findIndex(e => e.id === prev.start!.empId);
        const endEmpIdx = employees.findIndex(e => e.id === empId);
        const startDay = prev.start!.day;
        const endDay = day;

        const minEmp = Math.min(startEmpIdx, endEmpIdx);
        const maxEmp = Math.max(startEmpIdx, endEmpIdx);
        const minDay = Math.min(startDay, endDay);
        const maxDay = Math.max(startDay, endDay);

        for (let i = minEmp; i <= maxEmp; i++) {
          for (let d = minDay; d <= maxDay; d++) {
            newSet.add(`${employees[i].id}_${d}`);
          }
        }
      } else {
        if (ctrlKey && newSet.has(key)) {
          newSet.delete(key);
        } else {
          newSet.add(key);
        }
      }
      const newStart = shiftKey ? prev.start : { empId, day };
      return { start: newStart, current: { empId, day }, selectedCells: newSet };
    });
  };

  // --- Export/Import JSON (Backup) ---
  const handleExport = () => {
    const fileName = `${data.metadata.hotel}_${data.metadata.departamento}_${data.metadata.año}_${String(data.metadata.mes).padStart(2, '0')}.json`.replace(/\s/g, '_');
    const blob = new Blob([JSON.stringify({ ...data, empleados: employees }, null, 2)], { type: 'application/json' });
    const href = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = href;
    link.download = fileName;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (isMonthLocked) {
      alert("No se pueden importar datos en un mes cerrado.");
      return;
    }
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = JSON.parse(event.target?.result as string);
        if (json.metadata && json.empleados) {
          onUpdateData(json);
          setEmployees(json.empleados);
        } else {
          alert('Formato de archivo inválido');
        }
      } catch (err) {
        alert('Error leyendo archivo');
      }
    };
    reader.readAsText(file);
  };

  // --- Employee CRUD (Replicated) ---
  const handleSaveEmployee = (emp: Employee) => {
    // 1. Update Local State (Current Month)
    if (employees.find(e => e.id === emp.id)) {
      setEmployees(prev => prev.map(e => e.id === emp.id ? emp : e));
    } else {
      setEmployees(prev => [...prev, emp]);
    }

    // 2. Replicate to "Server" (All Months)
    syncEmployeeAcrossMonths(data.metadata.hotel, data.metadata.departamento, emp);
  };

  const handleDeleteEmployee = (id: string) => {
    // 1. Update Local State
    setEmployees(prev => prev.filter(e => e.id !== id));

    // 2. Replicate to "Server" (All Months)
    deleteEmployeeAcrossMonths(data.metadata.hotel, data.metadata.departamento, id);
  };

  return (
    <div className="flex flex-col h-screen bg-gray-50 text-gray-900">

      {/* Header */}
      <header className="bg-white shadow z-30 px-4 py-2 flex justify-between items-center border-b border-gray-200">
        <div className="flex items-center gap-4">
          <button onClick={onBack} className="text-gray-600 hover:text-blue-600 font-bold flex items-center gap-1">
            ← Volver
          </button>
          <div className="text-sm">
            <span className="font-bold text-gray-800">{data.metadata.hotel}</span>
            <span className="mx-2 text-gray-400">|</span>
            <span className="text-blue-600 font-medium">{data.metadata.departamento}</span>
            <span className="mx-2 text-gray-400">|</span>
            <span className="text-gray-600">{MONTHS[data.metadata.mes - 1]} {data.metadata.año}</span>
          </div>
        </div>

        <div className="flex items-center gap-2">
          {/* Download Dropdown */}
          <div className="relative" ref={downloadMenuRef}>
            <button 
              onClick={() => setShowDownloadMenu(!showDownloadMenu)}
              className="flex items-center gap-1 px-3 py-1 bg-green-100 text-green-800 rounded hover:bg-green-200 text-sm font-medium transition-colors"
            >
              📥 Descargar Informe ▼
            </button>
            {showDownloadMenu && (
              <div className="absolute right-0 mt-2 w-48 bg-white rounded-md shadow-lg py-1 z-50 border border-gray-200">
                <button 
                  onClick={() => { generatePDFReport(data, employees); setShowDownloadMenu(false); }}
                  className="block px-4 py-2 text-sm text-gray-700 hover:bg-gray-100 w-full text-left flex items-center gap-2"
                >
                  📄 Formato PDF (Horizontal)
                </button>
                <button 
                  onClick={() => { generateExcelReport(data, employees); setShowDownloadMenu(false); }}
                  className="block px-4 py-2 text-sm text-gray-700 hover:bg-gray-100 w-full text-left flex items-center gap-2"
                >
                  📊 Formato Excel (.xlsx)
                </button>
              </div>
            )}
          </div>

          <div className="h-6 w-px bg-gray-300 mx-1"></div>

          <button 
            onClick={() => { setEditingEmpId(null); setShowEmpModal(true); }} 
            className={`px-3 py-1 rounded text-sm font-medium ${isMonthLocked ? 'bg-gray-200 text-gray-400 cursor-not-allowed' : 'bg-blue-50 text-blue-700 hover:bg-blue-100'}`}
            disabled={isMonthLocked}
            title={isMonthLocked ? 'Mes cerrado' : 'Gestionar Empleados'}
          >
            👤 Empleados
          </button>
          <button 
            onClick={handleExport} 
            className="px-3 py-1 bg-gray-100 text-gray-700 rounded hover:bg-gray-200 text-sm font-medium"
          >
            💾 Backup JSON
          </button>
          <label className={`px-3 py-1 bg-gray-100 text-gray-700 rounded text-sm font-medium ${isMonthLocked ? 'cursor-not-allowed opacity-50' : 'cursor-pointer hover:bg-gray-200'}`}>
            📂 Restaurar JSON
            <input type="file" className="hidden" accept=".json" onChange={handleImport} disabled={isMonthLocked} />
          </label>
          <button onClick={() => setShowManual(true)} className="px-3 py-1 bg-yellow-50 text-yellow-700 rounded hover:bg-yellow-100 text-sm font-medium">
            ❓ Ayuda
          </button>
        </div>
      </header>

      {/* Locked Month Banner */}
      {isMonthLocked && (
        <div className="bg-red-500 text-white text-center py-2 px-4 text-sm font-bold shadow-md z-40">
          🔒 ESTE MES ESTÁ CERRADO. Solo lectura permitida.
        </div>
      )}

      {/* Legend Toggle */}
      <div className="bg-white border-b border-gray-100 px-4 py-1">
        <button 
          onClick={() => setShowLegend(!showLegend)} 
          className="text-xs text-gray-500 hover:text-blue-600 flex items-center gap-1 w-full"
        >
          {showLegend ? '▼ Ocultar Leyenda' : '▶ Mostrar Leyenda'}
        </button>
      </div>

      {/* Legend */}
      {showLegend && (
        <div className="bg-white p-3 border-b border-gray-200 grid grid-cols-2 md:grid-cols-4 lg:grid-cols-7 gap-2 text-xs overflow-y-auto max-h-32">
          {CODES.map(c => (
            <div key={c.code} className="flex items-center gap-2">
              <span className="w-6 h-6 flex items-center justify-center font-bold rounded border shadow-sm" style={{ backgroundColor: c.bgColor, color: c.textColor }}>
                {c.code}
              </span>
              <span className="truncate" title={c.name}>{c.name} <span className="text-gray-400">({c.key.toUpperCase()})</span></span>
            </div>
          ))}
        </div>
      )}

      {/* Main Toolbar */}
      <Toolbar onApplyCode={handleApplyCode} readOnly={isMonthLocked} />

      {/* Grid Area */}
      <div className="flex-1 overflow-hidden relative">
        <AttendanceGrid 
          year={data.metadata.año}
          month={data.metadata.mes}
          employees={employees}
          selection={selection}
          setSelection={setSelection}
          onCellClick={handleCellClick}
          onEditEmployee={(id) => { 
            // Allow opening modal to view data even if locked, but maybe set internal modal state to readonly? 
            // For now, we will allow opening to VIEW, assuming user won't save if disabled, 
            // but for safety we blocked the 'Save' inside modal if we passed a readonly prop.
            // Since EmployeeModal doesn't have readonly prop yet, we rely on the header button being disabled for 'New'.
            // For editing existing, let's just allow it for name fixes (replicated) BUT block grid edits.
            // Requirement says "Solo se podrá visualizar".
            if (!isMonthLocked) {
              setEditingEmpId(id); 
              setShowEmpModal(true);
            }
          }}
          readOnly={isMonthLocked}
        />

        {/* Status Toast */}
        {saveStatus === 'saving' && (
          <div className="absolute bottom-10 right-10 bg-blue-600/90 text-white px-4 py-2 rounded-full text-sm font-medium flex items-center gap-2 shadow-lg z-50">
            <span className="animate-spin h-3 w-3 border-2 border-white border-t-transparent rounded-full"></span>
            Sincronizando...
          </div>
        )}
        {saveStatus === 'saved' && (
          <div className="absolute bottom-10 right-10 bg-green-600/90 text-white px-4 py-2 rounded-full text-sm font-medium shadow-lg z-50">
            ✓ Guardado en servidor
          </div>
        )}
      </div>

      {/* Modals */}
      <EmployeeModal 
        isOpen={showEmpModal} 
        onClose={() => setShowEmpModal(false)}
        employees={employees}
        editId={editingEmpId}
        onSave={handleSaveEmployee}
        onDelete={handleDeleteEmployee}
      />

      <ManualModal isOpen={showManual} onClose={() => setShowManual(false)} />

    </div>
  );
};

export default QuadrantScreen;

import * as XLSX from 'xlsx';
import { jsPDF } from 'jspdf';
import autoTable from 'jspdf-autotable';
import { AppData, Employee } from '../types';
import { CODES, MONTHS, SC_CODE } from '../constants';

// --- LOGICA COMÚN ---
const prepareDataForReport = (data: AppData, employees: Employee[]) => {
  const { año, mes } = data.metadata;
  const daysInMonth = new Date(año, mes, 0).getDate();

  const headers = ['Empleado'];
  for (let i = 1; i <= daysInMonth; i++) headers.push(String(i));

  const body = employees.map(emp => {
    const row = [emp.nombre];
    const alta = new Date(emp.fechaAlta);
    const baja = emp.fechaBaja ? new Date(emp.fechaBaja) : null;

    for (let d = 1; d <= daysInMonth; d++) {
      const dateCheck = new Date(año, mes - 1, d);
      let cellValue = emp.asistencia[String(d)] || '';

      // Resetear hora para comparación justa
      dateCheck.setHours(0,0,0,0);
      const altaNorm = new Date(alta); altaNorm.setHours(0,0,0,0);
      const bajaNorm = baja ? new Date(baja) : null;
      if(bajaNorm) bajaNorm.setHours(0,0,0,0);

      if (dateCheck < altaNorm) cellValue = 'SC';
      else if (bajaNorm && dateCheck > bajaNorm) cellValue = 'SC';

      row.push(cellValue);
    }
    return row;
  });

  return { headers, body, daysInMonth };
};

// Helper para convertir HEX a RGB
const hexToRgb = (hex: string) => {
  const cleanHex = hex.replace('#', '');
  const r = parseInt(cleanHex.substring(0, 2), 16);
  const g = parseInt(cleanHex.substring(2, 4), 16);
  const b = parseInt(cleanHex.substring(4, 6), 16);
  return [r, g, b];
};

// --- EXCEL ---
export const generateExcelReport = (data: AppData, employees: Employee[]) => {
  const { hotel, departamento, año, mes } = data.metadata;
  const monthName = MONTHS[mes - 1];
  const { headers, body, daysInMonth } = prepareDataForReport(data, employees);

  // 1. Títulos
  const wsData: any[][] = [
    [`CONTROL DE ASISTENCIA - ${hotel.toUpperCase()}`],
    [`Departamento: ${departamento} | Período: ${monthName} ${año}`],
    [],
    headers,
    ...body
  ];

  // 2. Fila Ratios (Simplificada)
  const ratioRow: any[] = ['RATIO PERSONAL'];
  for (let d = 1; d <= daysInMonth; d++) {
    // Calculo simple para el reporte
    let total = 0;
    employees.forEach(emp => {
      const alta = new Date(emp.fechaAlta);
      const baja = emp.fechaBaja ? new Date(emp.fechaBaja) : null;
      const dateCheck = new Date(año, mes - 1, d);

      // Normalizar fechas
      dateCheck.setHours(0,0,0,0);
      alta.setHours(0,0,0,0);
      if(baja) baja.setHours(0,0,0,0);

      let status = emp.asistencia[String(d)];

      if (dateCheck < alta || (baja && dateCheck > baja)) return;

      const code = CODES.find(c => c.code === status);
      if (code) total += code.ratio;
    });
    ratioRow.push(total % 1 === 0 ? total : total.toFixed(1));
  }
  wsData.push(ratioRow);

  const ws = XLSX.utils.aoa_to_sheet(wsData);

  // Estilos Columnas
  const wscols = [{ wch: 30 }];
  for (let i = 1; i <= daysInMonth; i++) wscols.push({ wch: 4 });
  ws['!cols'] = wscols;

  // Leyenda
  const legendData = [
    ['CÓDIGO', 'DESCRIPCIÓN', 'RATIO', 'TECLA'],
    ...CODES.map(c => [c.code, c.name, c.ratio, c.key.toUpperCase()]),
    ['SC', 'Sin Contrato', 0, '-']
  ];
  const wsLegend = XLSX.utils.aoa_to_sheet(legendData);

  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, "Cuadrante");
  XLSX.utils.book_append_sheet(wb, wsLegend, "Leyenda");

  XLSX.writeFile(wb, `Informe_${hotel.replace(/\s/g, '')}_${departamento}_${monthName}_${año}.xlsx`);
};

// --- PDF ---
export const generatePDFReport = (data: AppData, employees: Employee[]) => {
  const { hotel, departamento, año, mes } = data.metadata;
  const monthName = MONTHS[mes - 1];
  const { headers, body } = prepareDataForReport(data, employees);

  const doc = new jsPDF({ orientation: 'landscape' });

  // Título
  doc.setFontSize(18);
  doc.setTextColor(40);
  doc.text(`CONTROL DE ASISTENCIA - ${hotel}`, 14, 15);
  doc.setFontSize(12);
  doc.setTextColor(100);
  doc.text(`Departamento: ${departamento} | Mes: ${monthName} ${año}`, 14, 22);

  // --- TABLA PRINCIPAL ---
  autoTable(doc, {
    startY: 28,
    head: [headers],
    body: body,
    theme: 'grid',
    styles: { fontSize: 7, cellPadding: 1, halign: 'center', lineColor: [200, 200, 200] },
    headStyles: { fillColor: [21, 101, 192], textColor: 255, fontStyle: 'bold' },
    columnStyles: { 0: { halign: 'left', cellWidth: 40, fontStyle: 'bold' } }, // Nombre más ancho
    didParseCell: (data) => {
      // Colorear celdas según código
      if (data.section === 'body' && data.column.index > 0) {
        const codeStr = data.cell.raw as string;
        if (codeStr === 'SC') {
          const rgb = hexToRgb(SC_CODE.bgColor);
          data.cell.styles.fillColor = [rgb[0], rgb[1], rgb[2]];
          const textRgb = hexToRgb(SC_CODE.textColor);
          data.cell.styles.textColor = [textRgb[0], textRgb[1], textRgb[2]];
        } else {
          const code = CODES.find(c => c.code === codeStr);
          if (code) {
            const rgb = hexToRgb(code.bgColor);
            data.cell.styles.fillColor = [rgb[0], rgb[1], rgb[2]];
            data.cell.styles.textColor = code.textColor === '#FFFFFF' ? 255 : 0;
          }
        }
      }
    }
  });

  // --- LEYENDA ---
  let finalY = (doc as any).lastAutoTable.finalY || 30;

  // Si queda poco espacio, saltar página
  if (finalY > 150) {
    doc.addPage();
    finalY = 20;
  } else {
    finalY += 10;
  }

  doc.setFontSize(10);
  doc.setTextColor(0);
  doc.text("Leyenda de Códigos:", 14, finalY);

  const legendBody = CODES.map(c => [c.code, c.name, c.ratio]);
  legendBody.push(['SC', 'Sin Contrato', 0]);

  autoTable(doc, {
    startY: finalY + 5,
    head: [['Código', 'Descripción', 'Ratio']],
    body: legendBody,
    theme: 'grid',
    styles: { fontSize: 8, cellPadding: 2, valign: 'middle' },
    headStyles: { fillColor: [66, 66, 66], textColor: 255 },
    columnStyles: {
      0: { halign: 'center', fontStyle: 'bold', cellWidth: 20 },
      1: { cellWidth: 'auto' },
      2: { halign: 'center', cellWidth: 15 }
    },
    // AQUÍ ESTÁ LA MAGIA: Colorear la primera columna igual que en la web
    didParseCell: (data) => {
      if (data.section === 'body' && data.column.index === 0) {
        const codeStr = data.cell.raw as string;
        let bgColor = '#FFFFFF';
        let textColor = '#000000';

        if (codeStr === 'SC') {
          bgColor = SC_CODE.bgColor;
          textColor = SC_CODE.textColor;
        } else {
          const code = CODES.find(c => c.code === codeStr);
          if (code) {
            bgColor = code.bgColor;
            textColor = code.textColor;
          }
        }

        const bgRgb = hexToRgb(bgColor);
        data.cell.styles.fillColor = [bgRgb[0], bgRgb[1], bgRgb[2]];

        // Ajuste de color de texto para asegurar contraste en PDF
        data.cell.styles.textColor = textColor === '#FFFFFF' ? 255 : 0;
      }
    }
  });

  doc.save(`Informe_${hotel.replace(/\s/g, '')}_${departamento}_${monthName}_${año}.pdf`);
};

import { AppData, Employee } from '../types';

const getStorageKey = (hotel: string, dept: string, year: number, month: number) => {
  return `asistencia_${hotel.replace(/\s/g, '_')}_${dept.replace(/\s/g, '_')}_${year}_${month}`;
};

const getPrefix = (hotel: string, dept: string) => {
  return `asistencia_${hotel.replace(/\s/g, '_')}_${dept.replace(/\s/g, '_')}`;
};

export const saveToStorage = (data: AppData) => {
  const key = getStorageKey(data.metadata.hotel, data.metadata.departamento, data.metadata.año, data.metadata.mes);
  data.metadata.ultimaModificacion = new Date().toISOString();
  localStorage.setItem(key, JSON.stringify(data));
};

export const loadFromStorage = (hotel: string, dept: string, year: number, month: number): AppData | null => {
  const key = getStorageKey(hotel, dept, year, month);
  const data = localStorage.getItem(key);
  return data ? JSON.parse(data) : null;
};

/**
 * Busca en el localStorage cualquier archivo existente para este Hotel y Departamento
 * y devuelve la lista de empleados más reciente encontrada.
 * Útil para inicializar nuevos meses con la plantilla actual.
 */
export const findRecentEmployees = (hotel: string, dept: string): Employee[] => {
  const prefix = getPrefix(hotel, dept);
  let foundEmployees: Employee[] = [];
  let lastModDate = 0;

  for (let i = 0; i < localStorage.length; i++) {
    const key = localStorage.key(i);
    if (key && key.startsWith(prefix)) {
      try {
        const item = localStorage.getItem(key);
        if (!item) continue;
        const data: AppData = JSON.parse(item);

        const modTime = new Date(data.metadata.ultimaModificacion).getTime();
        // Nos quedamos con los datos del archivo modificado más recientemente
        if (modTime > lastModDate && data.empleados.length > 0) {
          lastModDate = modTime;
          foundEmployees = data.empleados;
        }
      } catch (e) {
        console.warn("Error parsing data for key:", key);
      }
    }
  }

  // Limpiamos la asistencia al importar empleados a un mes nuevo
  // pero mantenemos fechas de alta/baja y periodo de prueba
  return foundEmployees.map(emp => ({
    ...emp,
    asistencia: {} 
  }));
};

/**
 * REPLICACIÓN DE DATOS (Simulación de Backend)
 * Actualiza o Crea un empleado en TODOS los meses guardados para este Hotel/Dpto.
 */
export const syncEmployeeAcrossMonths = (hotel: string, dept: string, employee: Employee) => {
  const prefix = getPrefix(hotel, dept);

  // Recorrer todo el localStorage
  for (let i = 0; i < localStorage.length; i++) {
    const key = localStorage.key(i);
    if (key && key.startsWith(prefix)) {
      try {
        const item = localStorage.getItem(key);
        if (!item) continue;

        const data: AppData = JSON.parse(item);
        let found = false;

        // Buscar si el empleado ya existe en ese mes
        const updatedEmployees = data.empleados.map(emp => {
          if (emp.id === employee.id) {
            found = true;
            // Actualizamos datos maestros (Nombre, Fechas, Prueba)
            // PERO MANTENEMOS la asistencia de ESE mes específico
            return {
              ...employee,
              asistencia: emp.asistencia 
            };
          }
          return emp;
        });

        // Si no existía, lo añadimos (con asistencia vacía para ese mes)
        // La lógica de visualización (SC) se encargará de ocultarlo si las fechas no coinciden
        if (!found) {
          updatedEmployees.push({
            ...employee,
            asistencia: {} 
          });
        }

        data.empleados = updatedEmployees;
        data.metadata.ultimaModificacion = new Date().toISOString();
        localStorage.setItem(key, JSON.stringify(data));

      } catch (e) {
        console.error("Error syncing employee for key: " + key, e);
      }
    }
  }
};

/**
 * REPLICACIÓN DE DATOS
 * Elimina un empleado de TODOS los meses guardados.
 */
export const deleteEmployeeAcrossMonths = (hotel: string, dept: string, employeeId: string) => {
  const prefix = getPrefix(hotel, dept);

  for (let i = 0; i < localStorage.length; i++) {
    const key = localStorage.key(i);
    if (key && key.startsWith(prefix)) {
      try {
        const item = localStorage.getItem(key);
        if (!item) continue;

        const data: AppData = JSON.parse(item);

        // Filtrar el empleado eliminado
        const initialLength = data.empleados.length;
        data.empleados = data.empleados.filter(e => e.id !== employeeId);

        if (data.empleados.length !== initialLength) {
          data.metadata.ultimaModificacion = new Date().toISOString();
          localStorage.setItem(key, JSON.stringify(data));
        }
      } catch (e) {
        console.error("Error deleting employee for key: " + key, e);
      }
    }
  }
};

import React, { useState, useEffect } from 'react';
import SelectionScreen from './components/SelectionScreen';
import QuadrantScreen from './components/QuadrantScreen';
import ManualModal from './components/ManualModal';
import { AppData } from './types';
import { INITIAL_EMPLOYEES_MOCK } from './constants';
import { loadFromStorage, findRecentEmployees } from './services/storageService';

const App: React.FC = () => {
  const [currentScreen, setCurrentScreen] = useState<'selection' | 'quadrant'>('selection');
  const [appData, setAppData] = useState<AppData | null>(null);
  const [showManual, setShowManual] = useState(false);

  const handleStart = (hotel: string, dept: string, year: number, month: number) => {
    // 1. Intentar cargar datos existentes específicos para este mes
    const existing = loadFromStorage(hotel, dept, year, month);

    if (existing) {
      setAppData(existing);
    } else {
      // 2. Si es un mes NUEVO, intentamos buscar empleados existentes de otros meses
      // para mantener la continuidad de la plantilla (Replicación automática por fecha)
      const existingEmployees = findRecentEmployees(hotel, dept);

      const employeesToUse = existingEmployees.length > 0 
        ? existingEmployees 
        : INITIAL_EMPLOYEES_MOCK; // Solo usar Mock si es la PRIMERA VEZ absoluta en este dpto

      const newData: AppData = {
        metadata: {
          hotel,
          departamento: dept,
          año: year,
          mes: month,
          ultimaModificacion: new Date().toISOString()
        },
        empleados: employeesToUse
      };
      setAppData(newData);
    }
    setCurrentScreen('quadrant');
  };

  const handleBack = () => {
    setCurrentScreen('selection');
    setAppData(null);
  };

  return (
    <>
      {currentScreen === 'selection' && (
        <SelectionScreen onStart={handleStart} onOpenManual={() => setShowManual(true)} />
      )}

      {currentScreen === 'quadrant' && appData && (
        <QuadrantScreen 
          data={appData} 
          onBack={handleBack} 
          onUpdateData={setAppData}
        />
      )}

      <ManualModal isOpen={showManual} onClose={() => setShowManual(false)} />
    </>
  );
};

export default App;

import React, { useState, useEffect, useCallback, useRef, useMemo } from 'react';
import { AppData, Employee, SelectionState } from '../types';
import { CODES, MONTHS } from '../constants';
import AttendanceGrid from './AttendanceGrid';
import Toolbar from './Toolbar';
import EmployeeModal from './EmployeeModal';
import ManualModal from './ManualModal';
import { saveToStorage, loadFromStorage, syncEmployeeAcrossMonths, deleteEmployeeAcrossMonths } from '../services/storageService';
import { generateExcelReport, generatePDFReport } from '../services/reportService';

interface QuadrantScreenProps {
  data: AppData;
  onBack: () => void;
  onUpdateData: (newData: AppData) => void;
}

const QuadrantScreen: React.FC<QuadrantScreenProps> = ({ data, onBack, onUpdateData }) => {
  const [employees, setEmployees] = useState<Employee[]>(data.empleados);
  const [selection, setSelection] = useState<SelectionState>({ start: null, current: null, selectedCells: new Set() });
  const [showEmpModal, setShowEmpModal] = useState(false);
  const [editingEmpId, setEditingEmpId] = useState<string | null>(null);
  const [showManual, setShowManual] = useState(false);
  const [showLegend, setShowLegend] = useState(true);
  const [saveStatus, setSaveStatus] = useState<'saved' | 'saving' | null>(null);
  const [showDownloadMenu, setShowDownloadMenu] = useState(false);
  const downloadMenuRef = useRef<HTMLDivElement>(null);

  // --- Locking Logic ---
  const isMonthLocked = useMemo(() => {
    const { año, mes } = data.metadata;
    // Date(year, monthIndex, 0) gives last day of previous month index.
    const lastDayOfMonth = new Date(año, mes, 0); 

    // Lock date is 7 days after the end of the month
    const lockDate = new Date(lastDayOfMonth);
    lockDate.setDate(lockDate.getDate() + 7);
    lockDate.setHours(23, 59, 59, 999);

    return new Date() > lockDate;
  }, [data.metadata.año, data.metadata.mes]);

  // --- Persistence & Auto-Sync (Local Tab) ---
  useEffect(() => {
    const newData = { ...data, empleados: employees };

    setSaveStatus('saving');
    const timeout = setTimeout(() => {
        saveToStorage(newData);
        setSaveStatus('saved');
        setTimeout(() => setSaveStatus(null), 2000);
    }, 500);

    onUpdateData(newData);

    return () => clearTimeout(timeout);
  }, [employees]);

  // --- Real-time Sync (Cross-Tab) ---
  useEffect(() => {
    const handleStorageChange = (e: StorageEvent) => {
      // Verificar si la clave cambiada corresponde a los datos que estamos viendo
      const currentKey = `asistencia_${data.metadata.hotel.replace(/\s/g, '_')}_${data.metadata.departamento.replace(/\s/g, '_')}_${data.metadata.año}_${data.metadata.mes}`;

      if (e.key === currentKey && e.newValue) {
        try {
          const newData = JSON.parse(e.newValue);
          // Actualizar estado local desde el "servidor" (localStorage)
          setEmployees(newData.empleados);
          onUpdateData(newData);
        } catch (err) {
          console.error("Error syncing from storage event", err);
        }
      }
    };

    window.addEventListener('storage', handleStorageChange);
    return () => window.removeEventListener('storage', handleStorageChange);
  }, [data.metadata]);

  // Click outside to close download menu
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (downloadMenuRef.current && !downloadMenuRef.current.contains(event.target as Node)) {
        setShowDownloadMenu(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // --- Handlers ---

  const handleApplyCode = (code: string) => {
    if (isMonthLocked) return;
    if (selection.selectedCells.size === 0) return;

    setEmployees(prev => prev.map(emp => {
      const newAsistencia = { ...emp.asistencia };
      let modified = false;

      // Iterate 1-31
      for (let d = 1; d <= 31; d++) {
        const key = `${emp.id}_${d}`;
        if (selection.selectedCells.has(key)) {
           newAsistencia[String(d)] = code;
           modified = true;
        }
      }
      return modified ? { ...emp, asistencia: newAsistencia } : emp;
    }));
  };

  const handleKeydown = useCallback((e: KeyboardEvent) => {
    if (showEmpModal || showManual || (e.target as HTMLElement).tagName === 'INPUT') return;
    if (isMonthLocked) return;

    const key = e.key.toLowerCase();
    const found = CODES.find(c => c.key === key);
    if (found) {
      handleApplyCode(found.code);
      e.preventDefault();
    }
  }, [selection, showEmpModal, showManual, isMonthLocked]);

  useEffect(() => {
    window.addEventListener('keydown', handleKeydown);
    return () => window.removeEventListener('keydown', handleKeydown);
  }, [handleKeydown]);

  // --- Selection Logic ---
  const handleCellClick = (empId: string, day: number, ctrlKey: boolean, shiftKey: boolean) => {
    if (isMonthLocked) return;

    const key = `${empId}_${day}`;

    setSelection(prev => {
      const newSet = new Set(ctrlKey ? prev.selectedCells : (shiftKey ? prev.selectedCells : []));

      if (shiftKey && prev.start) {
        const startEmpIdx = employees.findIndex(e => e.id === prev.start!.empId);
        const endEmpIdx = employees.findIndex(e => e.id === empId);
        const startDay = prev.start!.day;
        const endDay = day;

        const minEmp = Math.min(startEmpIdx, endEmpIdx);
        const maxEmp = Math.max(startEmpIdx, endEmpIdx);
        const minDay = Math.min(startDay, endDay);
        const maxDay = Math.max(startDay, endDay);

        for (let i = minEmp; i <= maxEmp; i++) {
          for (let d = minDay; d <= maxDay; d++) {
            newSet.add(`${employees[i].id}_${d}`);
          }
        }
      } else {
        if (ctrlKey && newSet.has(key)) {
          newSet.delete(key);
        } else {
          newSet.add(key);
        }
      }
      const newStart = shiftKey ? prev.start : { empId, day };
      return { start: newStart, current: { empId, day }, selectedCells: newSet };
    });
  };

  // --- Export/Import JSON (Backup) ---
  const handleExport = () => {
    const fileName = `${data.metadata.hotel}_${data.metadata.departamento}_${data.metadata.año}_${String(data.metadata.mes).padStart(2, '0')}.json`.replace(/\s/g, '_');
    const blob = new Blob([JSON.stringify({ ...data, empleados: employees }, null, 2)], { type: 'application/json' });
    const href = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = href;
    link.download = fileName;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (isMonthLocked) {
      alert("No se pueden importar datos en un mes cerrado.");
      return;
    }
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = JSON.parse(event.target?.result as string);
        if (json.metadata && json.empleados) {
          onUpdateData(json);
          setEmployees(json.empleados);
        } else {
          alert('Formato de archivo inválido');
        }
      } catch (err) {
        alert('Error leyendo archivo');
      }
    };
    reader.readAsText(file);
  };

  // --- Employee CRUD (Replicated) ---
  const handleSaveEmployee = (emp: Employee) => {
    // 1. Update Local State (Current Month)
    if (employees.find(e => e.id === emp.id)) {
      setEmployees(prev => prev.map(e => e.id === emp.id ? emp : e));
    } else {
      setEmployees(prev => [...prev, emp]);
    }

    // 2. Replicate to "Server" (All Months)
    // Esto asegura que si editamos el nombre o fechas, se actualiza en el historial
    // y si creamos uno nuevo, se añade a otros meses existentes.
    syncEmployeeAcrossMonths(data.metadata.hotel, data.metadata.departamento, emp);
  };

  const handleDeleteEmployee = (id: string) => {
    // 1. Update Local State
    setEmployees(prev => prev.filter(e => e.id !== id));

    // 2. Replicate to "Server" (All Months)
    deleteEmployeeAcrossMonths(data.metadata.hotel, data.metadata.departamento, id);
  };

  return (
    <div className="flex flex-col h-screen bg-gray-50 text-gray-900">

      {/* Header */}
      <header className="bg-white shadow z-30 px-4 py-2 flex justify-between items-center border-b border-gray-200">
        <div className="flex items-center gap-4">
          <button onClick={onBack} className="text-gray-600 hover:text-blue-600 font-bold flex items-center gap-1">
            ← Volver
          </button>
          <div className="text-sm">
            <span className="font-bold text-gray-800">{data.metadata.hotel}</span>
            <span className="mx-2 text-gray-400">|</span>
            <span className="text-blue-600 font-medium">{data.metadata.departamento}</span>
            <span className="mx-2 text-gray-400">|</span>
            <span className="text-gray-600">{MONTHS[data.metadata.mes - 1]} {data.metadata.año}</span>
          </div>
        </div>

        <div className="flex items-center gap-2">
          {/* Download Dropdown */}
          <div className="relative" ref={downloadMenuRef}>
            <button 
              onClick={() => setShowDownloadMenu(!showDownloadMenu)}
              className="flex items-center gap-1 px-3 py-1 bg-green-100 text-green-800 rounded hover:bg-green-200 text-sm font-medium transition-colors"
            >
              📥 Descargar Informe ▼
            </button>
            {showDownloadMenu && (
              <div className="absolute right-0 mt-2 w-48 bg-white rounded-md shadow-lg py-1 z-50 border border-gray-200">
                <button 
                  onClick={() => { generatePDFReport(data, employees); setShowDownloadMenu(false); }}
                  className="block px-4 py-2 text-sm text-gray-700 hover:bg-gray-100 w-full text-left flex items-center gap-2"
                >
                  📄 Formato PDF (Horizontal)
                </button>
                <button 
                  onClick={() => { generateExcelReport(data, employees); setShowDownloadMenu(false); }}
                  className="block px-4 py-2 text-sm text-gray-700 hover:bg-gray-100 w-full text-left flex items-center gap-2"
                >
                  📊 Formato Excel (.xlsx)
                </button>
              </div>
            )}
          </div>

          <div className="h-6 w-px bg-gray-300 mx-1"></div>

          <button 
            onClick={() => { setEditingEmpId(null); setShowEmpModal(true); }} 
            className={`px-3 py-1 rounded text-sm font-medium ${isMonthLocked ? 'bg-gray-200 text-gray-400 cursor-not-allowed' : 'bg-blue-50 text-blue-700 hover:bg-blue-100'}`}
            disabled={isMonthLocked}
            title={isMonthLocked ? 'Mes cerrado' : 'Gestionar Empleados'}
          >
            👤 Empleados
          </button>
          <button 
            onClick={handleExport} 
            className="px-3 py-1 bg-gray-100 text-gray-700 rounded hover:bg-gray-200 text-sm font-medium"
          >
            💾 Backup JSON
          </button>
          <label className={`px-3 py-1 bg-gray-100 text-gray-700 rounded text-sm font-medium ${isMonthLocked ? 'cursor-not-allowed opacity-50' : 'cursor-pointer hover:bg-gray-200'}`}>
            📂 Restaurar JSON
            <input type="file" className="hidden" accept=".json" onChange={handleImport} disabled={isMonthLocked} />
          </label>
          <button onClick={() => setShowManual(true)} className="px-3 py-1 bg-yellow-50 text-yellow-700 rounded hover:bg-yellow-100 text-sm font-medium">
            ❓ Ayuda
          </button>
        </div>
      </header>

      {/* Locked Month Banner */}
      {isMonthLocked && (
        <div className="bg-red-500 text-white text-center py-2 px-4 text-sm font-bold shadow-md z-40">
          🔒 ESTE MES ESTÁ CERRADO. Solo lectura permitida.
        </div>
      )}

      {/* Legend Toggle */}
      <div className="bg-white border-b border-gray-100 px-4 py-1">
        <button 
          onClick={() => setShowLegend(!showLegend)} 
          className="text-xs text-gray-500 hover:text-blue-600 flex items-center gap-1 w-full"
        >
          {showLegend ? '▼ Ocultar Leyenda' : '▶ Mostrar Leyenda'}
        </button>
      </div>

      {/* Legend */}
      {showLegend && (
        <div className="bg-white p-3 border-b border-gray-200 grid grid-cols-2 md:grid-cols-4 lg:grid-cols-7 gap-2 text-xs overflow-y-auto max-h-32">
          {CODES.map(c => (
            <div key={c.code} className="flex items-center gap-2">
              <span className="w-6 h-6 flex items-center justify-center font-bold rounded border shadow-sm" style={{ backgroundColor: c.bgColor, color: c.textColor }}>
                {c.code}
              </span>
              <span className="truncate" title={c.name}>{c.name} <span className="text-gray-400">({c.key.toUpperCase()})</span></span>
            </div>
          ))}
        </div>
      )}

      {/* Main Toolbar */}
      <Toolbar onApplyCode={handleApplyCode} readOnly={isMonthLocked} />

      {/* Grid Area */}
      <div className="flex-1 overflow-hidden relative">
        <AttendanceGrid 
          year={data.metadata.año}
          month={data.metadata.mes}
          employees={employees}
          selection={selection}
          setSelection={setSelection}
          onCellClick={handleCellClick}
          onEditEmployee={(id) => { 
            if (!isMonthLocked) {
              setEditingEmpId(id); 
              setShowEmpModal(true);
            }
          }}
          readOnly={isMonthLocked}
        />

        {/* Status Toast */}
        {saveStatus === 'saving' && (
          <div className="absolute bottom-10 right-10 bg-blue-600/90 text-white px-4 py-2 rounded-full text-sm font-medium flex items-center gap-2 shadow-lg z-50">
            <span className="animate-spin h-3 w-3 border-2 border-white border-t-transparent rounded-full"></span>
            Sincronizando...
          </div>
        )}
        {saveStatus === 'saved' && (
          <div className="absolute bottom-10 right-10 bg-green-600/90 text-white px-4 py-2 rounded-full text-sm font-medium shadow-lg z-50">
            ✓ Guardado en servidor
          </div>
        )}
      </div>

      {/* Modals */}
      <EmployeeModal 
        isOpen={showEmpModal} 
        onClose={() => setShowEmpModal(false)}
        employees={employees}
        editId={editingEmpId}
        onSave={handleSaveEmployee}
        onDelete={handleDeleteEmployee}
      />

      <ManualModal isOpen={showManual} onClose={() => setShowManual(false)} />

    </div>
  );
};

export default QuadrantScreen;

import * as XLSX from 'xlsx';
import { jsPDF } from 'jspdf';
import autoTable from 'jspdf-autotable';
import { AppData, Employee } from '../types';
import { CODES, MONTHS, SC_CODE } from '../constants';

// --- LOGICA COMÚN ---
const prepareDataForReport = (data: AppData, employees: Employee[]) => {
  const { año, mes } = data.metadata;
  const daysInMonth = new Date(año, mes, 0).getDate();

  const headers = ['Empleado'];
  for (let i = 1; i <= daysInMonth; i++) headers.push(String(i));

  const body = employees.map(emp => {
    const row = [emp.nombre];
    const alta = new Date(emp.fechaAlta);
    const baja = emp.fechaBaja ? new Date(emp.fechaBaja) : null;

    for (let d = 1; d <= daysInMonth; d++) {
      const dateCheck = new Date(año, mes - 1, d);
      let cellValue = emp.asistencia[String(d)] || '';

      // Resetear hora para comparación justa
      dateCheck.setHours(0,0,0,0);
      const altaNorm = new Date(alta); altaNorm.setHours(0,0,0,0);
      const bajaNorm = baja ? new Date(baja) : null;
      if(bajaNorm) bajaNorm.setHours(0,0,0,0);

      if (dateCheck < altaNorm) cellValue = 'SC';
      else if (bajaNorm && dateCheck > bajaNorm) cellValue = 'SC';

      row.push(cellValue);
    }
    return row;
  });

  return { headers, body, daysInMonth };
};

// Helper para calcular ratios (usado en Excel y PDF)
const calculateRatios = (data: AppData, employees: Employee[], daysInMonth: number) => {
  const { año, mes } = data.metadata;
  const ratios = [];

  for (let d = 1; d <= daysInMonth; d++) {
    let total = 0;
    employees.forEach(emp => {
      const alta = new Date(emp.fechaAlta);
      const baja = emp.fechaBaja ? new Date(emp.fechaBaja) : null;
      const dateCheck = new Date(año, mes - 1, d);

      dateCheck.setHours(0,0,0,0);
      alta.setHours(0,0,0,0);
      if(baja) baja.setHours(0,0,0,0);

      let status = emp.asistencia[String(d)];

      if (dateCheck < alta || (baja && dateCheck > baja)) return;

      const code = CODES.find(c => c.code === status);
      if (code) total += code.ratio;
    });
    ratios.push(total % 1 === 0 ? total : total.toFixed(1));
  }
  return ratios;
};

// Helper para convertir HEX a RGB
const hexToRgb = (hex: string) => {
  const cleanHex = hex.replace('#', '');
  const r = parseInt(cleanHex.substring(0, 2), 16);
  const g = parseInt(cleanHex.substring(2, 4), 16);
  const b = parseInt(cleanHex.substring(4, 6), 16);
  return [r, g, b];
};

// --- EXCEL ---
export const generateExcelReport = (data: AppData, employees: Employee[]) => {
  const { hotel, departamento, año, mes } = data.metadata;
  const monthName = MONTHS[mes - 1];
  const { headers, body, daysInMonth } = prepareDataForReport(data, employees);
  const ratios = calculateRatios(data, employees, daysInMonth);

  // 1. Títulos
  const wsData: any[][] = [
    [`CONTROL DE ASISTENCIA - ${hotel.toUpperCase()}`],
    [`Departamento: ${departamento} | Período: ${monthName} ${año}`],
    [],
    headers,
    ...body
  ];

  // 2. Fila Ratios
  const ratioRow = ['RATIO PERSONAL', ...ratios];
  wsData.push(ratioRow);

  const ws = XLSX.utils.aoa_to_sheet(wsData);

  // Estilos Columnas
  const wscols = [{ wch: 30 }];
  for (let i = 1; i <= daysInMonth; i++) wscols.push({ wch: 4 });
  ws['!cols'] = wscols;

  // Leyenda (4 columnas)
  const legendData = [
    ['CÓDIGO', 'DESCRIPCIÓN', 'RATIO', 'TECLA'],
    ...CODES.map(c => [c.code, c.name, c.ratio, c.key.toUpperCase()]),
    ['SC', 'Sin Contrato', 0, '-']
  ];
  const wsLegend = XLSX.utils.aoa_to_sheet(legendData);

  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, "Cuadrante");
  XLSX.utils.book_append_sheet(wb, wsLegend, "Leyenda");

  XLSX.writeFile(wb, `Informe_${hotel.replace(/\s/g, '')}_${departamento}_${monthName}_${año}.xlsx`);
};

// --- PDF ---
export const generatePDFReport = (data: AppData, employees: Employee[]) => {
  const { hotel, departamento, año, mes } = data.metadata;
  const monthName = MONTHS[mes - 1];
  const { headers, body, daysInMonth } = prepareDataForReport(data, employees);

  // Agregar fila de ratios al body
  const ratios = calculateRatios(data, employees, daysInMonth);
  const ratioRow = ['RATIO PERSONAL', ...ratios];
  const finalBody = [...body, ratioRow];

  const doc = new jsPDF({ orientation: 'landscape' });

  // Título
  doc.setFontSize(18);
  doc.setTextColor(40);
  doc.text(`CONTROL DE ASISTENCIA - ${hotel}`, 14, 15);
  doc.setFontSize(12);
  doc.setTextColor(100);
  doc.text(`Departamento: ${departamento} | Mes: ${monthName} ${año}`, 14, 22);

  // --- TABLA PRINCIPAL ---
  autoTable(doc, {
    startY: 28,
    head: [headers],
    body: finalBody,
    theme: 'grid',
    styles: { fontSize: 7, cellPadding: 1, halign: 'center', lineColor: [200, 200, 200] },
    headStyles: { fillColor: [21, 101, 192], textColor: 255, fontStyle: 'bold' },
    columnStyles: { 0: { halign: 'left', cellWidth: 40, fontStyle: 'bold' } }, // Nombre más ancho
    didParseCell: (data) => {
      // 1. Estilo para la fila de RATIO (Última fila)
      if (data.section === 'body' && data.row.index === finalBody.length - 1) {
        data.cell.styles.fillColor = [38, 50, 56]; // #263238 (Color web)
        data.cell.styles.textColor = 255;
        data.cell.styles.fontStyle = 'bold';
      }

      // 2. Colorear celdas según código (Solo si no es la fila de ratio y es columna de datos)
      if (data.section === 'body' && data.column.index > 0 && data.row.index < finalBody.length - 1) {
        const codeStr = data.cell.raw as string;
        if (codeStr === 'SC') {
          const rgb = hexToRgb(SC_CODE.bgColor);
          data.cell.styles.fillColor = [rgb[0], rgb[1], rgb[2]];
          const textRgb = hexToRgb(SC_CODE.textColor);
          data.cell.styles.textColor = [textRgb[0], textRgb[1], textRgb[2]];
        } else {
          const code = CODES.find(c => c.code === codeStr);
          if (code) {
            const rgb = hexToRgb(code.bgColor);
            data.cell.styles.fillColor = [rgb[0], rgb[1], rgb[2]];
            data.cell.styles.textColor = code.textColor === '#FFFFFF' ? 255 : 0;
          }
        }
      }
    }
  });

  // --- LEYENDA (4 Columnas) ---
  let finalY = (doc as any).lastAutoTable.finalY || 30;

  // Si queda poco espacio, saltar página
  if (finalY > 150) {
    doc.addPage();
    finalY = 20;
  } else {
    finalY += 10;
  }

  doc.setFontSize(10);
  doc.setTextColor(0);
  doc.text("Leyenda de Códigos:", 14, finalY);

  const legendBody = CODES.map(c => [c.code, c.name, c.ratio, c.key.toUpperCase()]);
  legendBody.push(['SC', 'Sin Contrato', 0, '-']);

  autoTable(doc, {
    startY: finalY + 5,
    head: [['Código', 'Descripción', 'Ratio', 'Tecla']],
    body: legendBody,
    theme: 'grid',
    styles: { fontSize: 8, cellPadding: 2, valign: 'middle' },
    headStyles: { fillColor: [66, 66, 66], textColor: 255 },
    columnStyles: {
      0: { halign: 'center', fontStyle: 'bold', cellWidth: 20 },
      1: { cellWidth: 'auto' },
      2: { halign: 'center', cellWidth: 15 },
      3: { halign: 'center', cellWidth: 15 }
    },
    // Colorear la primera columna igual que en la web
    didParseCell: (data) => {
      if (data.section === 'body' && data.column.index === 0) {
        const codeStr = data.cell.raw as string;
        let bgColor = '#FFFFFF';
        let textColor = '#000000';

        if (codeStr === 'SC') {
          bgColor = SC_CODE.bgColor;
          textColor = SC_CODE.textColor;
        } else {
          const code = CODES.find(c => c.code === codeStr);
          if (code) {
            bgColor = code.bgColor;
            textColor = code.textColor;
          }
        }

        const bgRgb = hexToRgb(bgColor);
        data.cell.styles.fillColor = [bgRgb[0], bgRgb[1], bgRgb[2]];
        data.cell.styles.textColor = textColor === '#FFFFFF' ? 255 : 0;
      }
    }
  });

  doc.save(`Informe_${hotel.replace(/\s/g, '')}_${departamento}_${monthName}_${año}.pdf`);
};

import React, { useState, useEffect } from 'react';
import { Employee } from '../types';

interface EmployeeModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (emp: Employee) => void;
  onDelete: (id: string) => void;
  onReorder: (employees: Employee[]) => void;
  employees: Employee[];
  editId: string | null;
}

const EmployeeModal: React.FC<EmployeeModalProps> = ({ isOpen, onClose, onSave, onDelete, onReorder, employees, editId }) => {
  const [formData, setFormData] = useState<Partial<Employee>>({
    nombre: '',
    fechaAlta: '',
    fechaBaja: null,
    periodoPrueba: { activo: false, dias: 60, fechaFin: null },
    asistencia: {}
  });

  const [activeTab, setActiveTab] = useState<'list' | 'form'>('list');

  useEffect(() => {
    if (isOpen) {
      if (editId) {
        const emp = employees.find(e => e.id === editId);
        if (emp) {
          setFormData(JSON.parse(JSON.stringify(emp))); // Deep copy
          setActiveTab('form');
        }
      } else {
        // Reset if opening without ID (via header button usually means list view first)
        setActiveTab('list');
        resetForm();
      }
    }
  }, [isOpen, editId, employees]);

  const resetForm = () => {
    setFormData({
      nombre: '',
      fechaAlta: new Date().toISOString().split('T')[0],
      fechaBaja: null,
      periodoPrueba: { activo: false, dias: 60, fechaFin: null },
      asistencia: {}
    });
  };

  const handleCreateNew = () => {
    resetForm();
    setActiveTab('form');
  }

  const handleEdit = (emp: Employee) => {
    setFormData(JSON.parse(JSON.stringify(emp)));
    setActiveTab('form');
  }

  const handleDelete = (id: string, nombre: string) => {
    if (window.confirm(`¿Eliminar a ${nombre}? Se perderán todos sus datos de asistencia.`)) {
      onDelete(id);
      if (editId === id) onClose();
    }
  }

  const handleMove = (index: number, direction: 'up' | 'down') => {
    if (direction === 'up' && index === 0) return;
    if (direction === 'down' && index === employees.length - 1) return;

    const newEmployees = [...employees];
    const targetIndex = direction === 'up' ? index - 1 : index + 1;

    // Swap
    [newEmployees[index], newEmployees[targetIndex]] = [newEmployees[targetIndex], newEmployees[index]];

    onReorder(newEmployees);
  };

  const calculateTrialEnd = (start: string, days: number) => {
    if (!start) return '';
    const date = new Date(start);
    date.setDate(date.getDate() + days);
    return date.toISOString().split('T')[0];
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.nombre || !formData.fechaAlta) return;

    const newEmp: Employee = {
      id: formData.id || `emp_${Date.now()}`,
      nombre: formData.nombre,
      fechaAlta: formData.fechaAlta,
      fechaBaja: formData.fechaBaja || null,
      periodoPrueba: {
        activo: formData.periodoPrueba?.activo || false,
        dias: formData.periodoPrueba?.dias || 0,
        fechaFin: formData.periodoPrueba?.activo 
          ? calculateTrialEnd(formData.fechaAlta, formData.periodoPrueba.dias) 
          : null
      },
      asistencia: formData.asistencia || {}
    };

    onSave(newEmp);
    if (editId) onClose(); // If direct edit, close
    else setActiveTab('list'); // If from list, go back to list
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
      <div className="bg-white rounded-xl shadow-2xl w-full max-w-4xl max-h-[90vh] flex flex-col overflow-hidden">

        {/* Header */}
        <div className="p-4 border-b bg-gray-50 flex justify-between items-center">
          <h2 className="text-xl font-bold text-gray-800">
            {activeTab === 'list' ? 'Gestión de Empleados' : (formData.id ? 'Editar Empleado' : 'Nuevo Empleado')}
          </h2>
          <button onClick={onClose} className="text-gray-500 hover:text-gray-700 text-2xl">&times;</button>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-auto p-6">
          {activeTab === 'list' ? (
            <div>
              <div className="flex justify-end mb-4">
                <button 
                  onClick={handleCreateNew}
                  className="bg-green-600 text-white px-4 py-2 rounded-lg hover:bg-green-700 flex items-center gap-2"
                >
                  <span>+</span> Añadir Empleado
                </button>
              </div>
              <table className="w-full text-left border-collapse">
                <thead>
                  <tr className="border-b bg-gray-50">
                    <th className="p-3 text-sm font-semibold text-gray-600 w-16 text-center">Orden</th>
                    <th className="p-3 text-sm font-semibold text-gray-600">Nombre</th>
                    <th className="p-3 text-sm font-semibold text-gray-600">Alta</th>
                    <th className="p-3 text-sm font-semibold text-gray-600">Baja</th>
                    <th className="p-3 text-sm font-semibold text-gray-600">Prueba</th>
                    <th className="p-3 text-sm font-semibold text-gray-600 text-right">Acciones</th>
                  </tr>
                </thead>
                <tbody>
                  {employees.map((emp, index) => (
                    <tr key={emp.id} className="border-b hover:bg-gray-50">
                      <td className="p-3 text-center">
                        <div className="flex flex-col gap-1 items-center justify-center">
                          <button 
                            onClick={() => handleMove(index, 'up')} 
                            disabled={index === 0}
                            className={`text-xs p-1 rounded hover:bg-blue-100 ${index === 0 ? 'text-gray-300' : 'text-blue-600'}`}
                            title="Subir"
                          >
                            ▲
                          </button>
                          <button 
                            onClick={() => handleMove(index, 'down')} 
                            disabled={index === employees.length - 1}
                            className={`text-xs p-1 rounded hover:bg-blue-100 ${index === employees.length - 1 ? 'text-gray-300' : 'text-blue-600'}`}
                            title="Bajar"
                          >
                            ▼
                          </button>
                        </div>
                      </td>
                      <td className="p-3 font-medium">{emp.nombre}</td>
                      <td className="p-3 text-sm text-gray-600">{emp.fechaAlta}</td>
                      <td className="p-3 text-sm text-gray-600">{emp.fechaBaja || '-'}</td>
                      <td className="p-3 text-sm">
                        {emp.periodoPrueba.activo ? (
                          <span className="bg-orange-100 text-orange-800 px-2 py-1 rounded text-xs">
                            ⏱️ {emp.periodoPrueba.dias} días
                          </span>
                        ) : (
                          <span className="text-gray-400 text-xs">Completado/No</span>
                        )}
                      </td>
                      <td className="p-3 text-right space-x-2">
                        <button onClick={() => handleEdit(emp)} className="text-blue-600 hover:text-blue-800">✏️</button>
                        <button onClick={() => handleDelete(emp.id, emp.nombre)} className="text-red-600 hover:text-red-800">🗑️</button>
                      </td>
                    </tr>
                  ))}
                  {employees.length === 0 && (
                    <tr>
                      <td colSpan={6} className="p-8 text-center text-gray-400">No hay empleados registrados.</td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>
          ) : (
            <form onSubmit={handleSubmit} className="space-y-6 max-w-2xl mx-auto">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Nombre Completo *</label>
                <input
                  type="text"
                  required
                  placeholder="Ej: Juan García López"
                  className="w-full p-2 border rounded focus:ring-2 focus:ring-blue-500"
                  value={formData.nombre}
                  onChange={e => setFormData({...formData, nombre: e.target.value})}
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Fecha de Alta *</label>
                  <input
                    type="date"
                    required
                    className="w-full p-2 border rounded focus:ring-2 focus:ring-blue-500"
                    value={formData.fechaAlta}
                    onChange={e => setFormData({...formData, fechaAlta: e.target.value})}
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Fecha de Baja</label>
                  <input
                    type="date"
                    className="w-full p-2 border rounded focus:ring-2 focus:ring-blue-500"
                    value={formData.fechaBaja || ''}
                    onChange={e => setFormData({...formData, fechaBaja: e.target.value || null})}
                  />
                  <p className="text-xs text-gray-500 mt-1">Dejar vacío si sigue activo</p>
                </div>
              </div>

              <div className="border p-4 rounded-lg bg-gray-50">
                <div className="flex items-center gap-2 mb-3">
                  <input
                    type="checkbox"
                    id="pp_active"
                    checked={formData.periodoPrueba?.activo}
                    onChange={e => setFormData({
                      ...formData, 
                      periodoPrueba: { ...formData.periodoPrueba!, activo: e.target.checked }
                    })}
                    className="w-4 h-4 text-blue-600 rounded"
                  />
                  <label htmlFor="pp_active" className="font-medium text-gray-700">Empleado en periodo de prueba</label>
                </div>

                {formData.periodoPrueba?.activo && (
                  <div className="ml-6 space-y-3">
                    <div className="flex gap-4">
                      {[45, 60, 120].map(days => (
                        <label key={days} className="flex items-center gap-1 cursor-pointer">
                          <input
                            type="radio"
                            name="pp_days"
                            checked={formData.periodoPrueba?.dias === days}
                            onChange={() => setFormData({
                              ...formData,
                              periodoPrueba: { ...formData.periodoPrueba!, dias: days }
                            })}
                          />
                          <span className="text-sm">{days} días</span>
                        </label>
                      ))}
                    </div>
                    <div className="text-sm text-gray-600 bg-white p-2 rounded border">
                      Fin del periodo: <strong>
                        {formData.fechaAlta ? calculateTrialEnd(formData.fechaAlta, formData.periodoPrueba!.dias) : 'Define fecha alta'}
                      </strong>
                    </div>
                  </div>
                )}
              </div>

              <div className="flex justify-end gap-3 pt-4 border-t">
                <button
                  type="button"
                  onClick={() => setActiveTab('list')}
                  className="px-4 py-2 text-gray-700 hover:bg-gray-100 rounded"
                >
                  Cancelar
                </button>
                <button
                  type="submit"
                  className="px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700 shadow"
                >
                  Guardar Empleado
                </button>
              </div>
            </form>
          )}
        </div>
      </div>
    </div>
  );
};

export default EmployeeModal;

import React, { useState, useEffect, useCallback, useRef, useMemo } from 'react';
import { AppData, Employee, SelectionState } from '../types';
import { CODES, MONTHS } from '../constants';
import AttendanceGrid from './AttendanceGrid';
import Toolbar from './Toolbar';
import EmployeeModal from './EmployeeModal';
import ManualModal from './ManualModal';
import { saveToStorage, loadFromStorage, syncEmployeeAcrossMonths, deleteEmployeeAcrossMonths } from '../services/storageService';
import { generateExcelReport, generatePDFReport } from '../services/reportService';

interface QuadrantScreenProps {
  data: AppData;
  onBack: () => void;
  onUpdateData: (newData: AppData) => void;
}

const QuadrantScreen: React.FC<QuadrantScreenProps> = ({ data, onBack, onUpdateData }) => {
  const [employees, setEmployees] = useState<Employee[]>(data.empleados);
  const [selection, setSelection] = useState<SelectionState>({ start: null, current: null, selectedCells: new Set() });
  const [showEmpModal, setShowEmpModal] = useState(false);
  const [editingEmpId, setEditingEmpId] = useState<string | null>(null);
  const [showManual, setShowManual] = useState(false);
  const [showLegend, setShowLegend] = useState(true);
  const [saveStatus, setSaveStatus] = useState<'saved' | 'saving' | null>(null);
  const [showDownloadMenu, setShowDownloadMenu] = useState(false);
  const downloadMenuRef = useRef<HTMLDivElement>(null);

  // --- Locking Logic ---
  const isMonthLocked = useMemo(() => {
    const { año, mes } = data.metadata;
    // Date(year, monthIndex, 0) gives last day of previous month index.
    const lastDayOfMonth = new Date(año, mes, 0); 

    // Lock date is 7 days after the end of the month
    const lockDate = new Date(lastDayOfMonth);
    lockDate.setDate(lockDate.getDate() + 7);
    lockDate.setHours(23, 59, 59, 999);

    return new Date() > lockDate;
  }, [data.metadata.año, data.metadata.mes]);

  // --- Persistence & Auto-Sync (Local Tab) ---
  useEffect(() => {
    const newData = { ...data, empleados: employees };

    setSaveStatus('saving');
    const timeout = setTimeout(() => {
        saveToStorage(newData);
        setSaveStatus('saved');
        setTimeout(() => setSaveStatus(null), 2000);
    }, 500);

    onUpdateData(newData);

    return () => clearTimeout(timeout);
  }, [employees]);

  // --- Real-time Sync (Cross-Tab) ---
  useEffect(() => {
    const handleStorageChange = (e: StorageEvent) => {
      // Verificar si la clave cambiada corresponde a los datos que estamos viendo
      const currentKey = `asistencia_${data.metadata.hotel.replace(/\s/g, '_')}_${data.metadata.departamento.replace(/\s/g, '_')}_${data.metadata.año}_${data.metadata.mes}`;

      if (e.key === currentKey && e.newValue) {
        try {
          const newData = JSON.parse(e.newValue);
          // Actualizar estado local desde el "servidor" (localStorage)
          setEmployees(newData.empleados);
          onUpdateData(newData);
        } catch (err) {
          console.error("Error syncing from storage event", err);
        }
      }
    };

    window.addEventListener('storage', handleStorageChange);
    return () => window.removeEventListener('storage', handleStorageChange);
  }, [data.metadata]);

  // Click outside to close download menu
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (downloadMenuRef.current && !downloadMenuRef.current.contains(event.target as Node)) {
        setShowDownloadMenu(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // --- Handlers ---

  const handleApplyCode = (code: string) => {
    if (isMonthLocked) return;
    if (selection.selectedCells.size === 0) return;

    setEmployees(prev => prev.map(emp => {
      const newAsistencia = { ...emp.asistencia };
      let modified = false;

      // Iterate 1-31
      for (let d = 1; d <= 31; d++) {
        const key = `${emp.id}_${d}`;
        if (selection.selectedCells.has(key)) {
           newAsistencia[String(d)] = code;
           modified = true;
        }
      }
      return modified ? { ...emp, asistencia: newAsistencia } : emp;
    }));
  };

  const handleKeydown = useCallback((e: KeyboardEvent) => {
    if (showEmpModal || showManual || (e.target as HTMLElement).tagName === 'INPUT') return;
    if (isMonthLocked) return;

    const key = e.key.toLowerCase();
    const found = CODES.find(c => c.key === key);
    if (found) {
      handleApplyCode(found.code);
      e.preventDefault();
    }
  }, [selection, showEmpModal, showManual, isMonthLocked]);

  useEffect(() => {
    window.addEventListener('keydown', handleKeydown);
    return () => window.removeEventListener('keydown', handleKeydown);
  }, [handleKeydown]);

  // --- Selection Logic ---
  const handleCellClick = (empId: string, day: number, ctrlKey: boolean, shiftKey: boolean) => {
    if (isMonthLocked) return;

    const key = `${empId}_${day}`;

    setSelection(prev => {
      const newSet = new Set(ctrlKey ? prev.selectedCells : (shiftKey ? prev.selectedCells : []));

      if (shiftKey && prev.start) {
        const startEmpIdx = employees.findIndex(e => e.id === prev.start!.empId);
        const endEmpIdx = employees.findIndex(e => e.id === empId);
        const startDay = prev.start!.day;
        const endDay = day;

        const minEmp = Math.min(startEmpIdx, endEmpIdx);
        const maxEmp = Math.max(startEmpIdx, endEmpIdx);
        const minDay = Math.min(startDay, endDay);
        const maxDay = Math.max(startDay, endDay);

        for (let i = minEmp; i <= maxEmp; i++) {
          for (let d = minDay; d <= maxDay; d++) {
            newSet.add(`${employees[i].id}_${d}`);
          }
        }
      } else {
        if (ctrlKey && newSet.has(key)) {
          newSet.delete(key);
        } else {
          newSet.add(key);
        }
      }
      const newStart = shiftKey ? prev.start : { empId, day };
      return { start: newStart, current: { empId, day }, selectedCells: newSet };
    });
  };

  // --- Export/Import JSON (Backup) ---
  const handleExport = () => {
    const fileName = `${data.metadata.hotel}_${data.metadata.departamento}_${data.metadata.año}_${String(data.metadata.mes).padStart(2, '0')}.json`.replace(/\s/g, '_');
    const blob = new Blob([JSON.stringify({ ...data, empleados: employees }, null, 2)], { type: 'application/json' });
    const href = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = href;
    link.download = fileName;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (isMonthLocked) {
      alert("No se pueden importar datos en un mes cerrado.");
      return;
    }
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = JSON.parse(event.target?.result as string);
        if (json.metadata && json.empleados) {
          onUpdateData(json);
          setEmployees(json.empleados);
        } else {
          alert('Formato de archivo inválido');
        }
      } catch (err) {
        alert('Error leyendo archivo');
      }
    };
    reader.readAsText(file);
  };

  // --- Employee CRUD (Replicated) ---
  const handleSaveEmployee = (emp: Employee) => {
    // 1. Update Local State (Current Month)
    if (employees.find(e => e.id === emp.id)) {
      setEmployees(prev => prev.map(e => e.id === emp.id ? emp : e));
    } else {
      setEmployees(prev => [...prev, emp]);
    }

    // 2. Replicate to "Server" (All Months)
    // Esto asegura que si editamos el nombre o fechas, se actualiza en el historial
    // y si creamos uno nuevo, se añade a otros meses existentes.
    syncEmployeeAcrossMonths(data.metadata.hotel, data.metadata.departamento, emp);
  };

  const handleDeleteEmployee = (id: string) => {
    // 1. Update Local State
    setEmployees(prev => prev.filter(e => e.id !== id));

    // 2. Replicate to "Server" (All Months)
    deleteEmployeeAcrossMonths(data.metadata.hotel, data.metadata.departamento, id);
  };

  return (
    <div className="flex flex-col h-screen bg-gray-50 text-gray-900">

      {/* Header */}
      <header className="bg-white shadow z-30 px-4 py-2 flex justify-between items-center border-b border-gray-200">
        <div className="flex items-center gap-4">
          <button onClick={onBack} className="text-gray-600 hover:text-blue-600 font-bold flex items-center gap-1">
            ← Volver
          </button>
          <div className="text-sm">
            <span className="font-bold text-gray-800">{data.metadata.hotel}</span>
            <span className="mx-2 text-gray-400">|</span>
            <span className="text-blue-600 font-medium">{data.metadata.departamento}</span>
            <span className="mx-2 text-gray-400">|</span>
            <span className="text-gray-600">{MONTHS[data.metadata.mes - 1]} {data.metadata.año}</span>
          </div>
        </div>

        <div className="flex items-center gap-2">
          {/* Download Dropdown */}
          <div className="relative" ref={downloadMenuRef}>
            <button 
              onClick={() => setShowDownloadMenu(!showDownloadMenu)}
              className="flex items-center gap-1 px-3 py-1 bg-green-100 text-green-800 rounded hover:bg-green-200 text-sm font-medium transition-colors"
            >
              📥 Descargar Informe ▼
            </button>
            {showDownloadMenu && (
              <div className="absolute right-0 mt-2 w-48 bg-white rounded-md shadow-lg py-1 z-50 border border-gray-200">
                <button 
                  onClick={() => { generatePDFReport(data, employees); setShowDownloadMenu(false); }}
                  className="block px-4 py-2 text-sm text-gray-700 hover:bg-gray-100 w-full text-left flex items-center gap-2"
                >
                  📄 Formato PDF (Horizontal)
                </button>
                <button 
                  onClick={() => { generateExcelReport(data, employees); setShowDownloadMenu(false); }}
                  className="block px-4 py-2 text-sm text-gray-700 hover:bg-gray-100 w-full text-left flex items-center gap-2"
                >
                  📊 Formato Excel (.xlsx)
                </button>
              </div>
            )}
          </div>

          <div className="h-6 w-px bg-gray-300 mx-1"></div>

          <button 
            onClick={() => { setEditingEmpId(null); setShowEmpModal(true); }} 
            className={`px-3 py-1 rounded text-sm font-medium ${isMonthLocked ? 'bg-gray-200 text-gray-400 cursor-not-allowed' : 'bg-blue-50 text-blue-700 hover:bg-blue-100'}`}
            disabled={isMonthLocked}
            title={isMonthLocked ? 'Mes cerrado' : 'Gestionar Empleados'}
          >
            👤 Empleados
          </button>
          <button 
            onClick={handleExport} 
            className="px-3 py-1 bg-gray-100 text-gray-700 rounded hover:bg-gray-200 text-sm font-medium"
          >
            💾 Backup JSON
          </button>
          <label className={`px-3 py-1 bg-gray-100 text-gray-700 rounded text-sm font-medium ${isMonthLocked ? 'cursor-not-allowed opacity-50' : 'cursor-pointer hover:bg-gray-200'}`}>
            📂 Restaurar JSON
            <input type="file" className="hidden" accept=".json" onChange={handleImport} disabled={isMonthLocked} />
          </label>
          <button onClick={() => setShowManual(true)} className="px-3 py-1 bg-yellow-50 text-yellow-700 rounded hover:bg-yellow-100 text-sm font-medium">
            ❓ Ayuda
          </button>
        </div>
      </header>

      {/* Locked Month Banner */}
      {isMonthLocked && (
        <div className="bg-red-500 text-white text-center py-2 px-4 text-sm font-bold shadow-md z-40">
          🔒 ESTE MES ESTÁ CERRADO. Solo lectura permitida.
        </div>
      )}

      {/* Legend Toggle */}
      <div className="bg-white border-b border-gray-100 px-4 py-1">
        <button 
          onClick={() => setShowLegend(!showLegend)} 
          className="text-xs text-gray-500 hover:text-blue-600 flex items-center gap-1 w-full"
        >
          {showLegend ? '▼ Ocultar Leyenda' : '▶ Mostrar Leyenda'}
        </button>
      </div>

      {/* Legend */}
      {showLegend && (
        <div className="bg-white p-3 border-b border-gray-200 grid grid-cols-2 md:grid-cols-4 lg:grid-cols-7 gap-2 text-xs overflow-y-auto max-h-32">
          {CODES.map(c => (
            <div key={c.code} className="flex items-center gap-2">
              <span className="w-6 h-6 flex items-center justify-center font-bold rounded border shadow-sm" style={{ backgroundColor: c.bgColor, color: c.textColor }}>
                {c.code}
              </span>
              <span className="truncate" title={c.name}>{c.name} <span className="text-gray-400">({c.key.toUpperCase()})</span></span>
            </div>
          ))}
        </div>
      )}

      {/* Main Toolbar */}
      <Toolbar onApplyCode={handleApplyCode} readOnly={isMonthLocked} />

      {/* Grid Area */}
      <div className="flex-1 overflow-hidden relative">
        <AttendanceGrid 
          year={data.metadata.año}
          month={data.metadata.mes}
          employees={employees}
          selection={selection}
          setSelection={setSelection}
          onCellClick={handleCellClick}
          onEditEmployee={(id) => { 
            if (!isMonthLocked) {
              setEditingEmpId(id); 
              setShowEmpModal(true);
            }
          }}
          readOnly={isMonthLocked}
        />

        {/* Status Toast */}
        {saveStatus === 'saving' && (
          <div className="absolute bottom-10 right-10 bg-blue-600/90 text-white px-4 py-2 rounded-full text-sm font-medium flex items-center gap-2 shadow-lg z-50">
            <span className="animate-spin h-3 w-3 border-2 border-white border-t-transparent rounded-full"></span>
            Sincronizando...
          </div>
        )}
        {saveStatus === 'saved' && (
          <div className="absolute bottom-10 right-10 bg-green-600/90 text-white px-4 py-2 rounded-full text-sm font-medium shadow-lg z-50">
            ✓ Guardado en servidor
          </div>
        )}
      </div>

      {/* Modals */}
      <EmployeeModal 
        isOpen={showEmpModal} 
        onClose={() => setShowEmpModal(false)}
        employees={employees}
        editId={editingEmpId}
        onSave={handleSaveEmployee}
        onDelete={handleDeleteEmployee}
        onReorder={setEmployees}
      />

      <ManualModal isOpen={showManual} onClose={() => setShowManual(false)} />

    </div>
  );
};

export default QuadrantScreen;

