import * as XLSX from 'xlsx';
import { jsPDF } from 'jspdf';
import autoTable from 'jspdf-autotable';
import { AppData, Employee } from '../types';
import { CODES, MONTHS, SC_CODE } from '../constants';

// --- LOGICA COMÚN ---
const prepareDataForReport = (data: AppData, employees: Employee[]) => {
  const { año, mes } = data.metadata;
  const daysInMonth = new Date(año, mes, 0).getDate();

  // Headers: Empleado | 1..31 | LT | L | V
  const headers = ['Empleado'];
  for (let i = 1; i <= daysInMonth; i++) headers.push(String(i));
  headers.push('L. Trab', 'L. Disfr', 'Vacac');

  const body = employees.map(emp => {
    const row = [emp.nombre];
    const alta = new Date(emp.fechaAlta);
    const baja = emp.fechaBaja ? new Date(emp.fechaBaja) : null;

    // Contadores
    let countLT = 0;
    let countL = 0;
    let countV = 0;

    for (let d = 1; d <= daysInMonth; d++) {
      const dateCheck = new Date(año, mes - 1, d);
      let cellValue = emp.asistencia[String(d)] || '';

      // Resetear hora para comparación justa
      dateCheck.setHours(0,0,0,0);
      const altaNorm = new Date(alta); altaNorm.setHours(0,0,0,0);
      const bajaNorm = baja ? new Date(baja) : null;
      if(bajaNorm) bajaNorm.setHours(0,0,0,0);

      // Lógica SC
      if (dateCheck < altaNorm) cellValue = 'SC';
      else if (bajaNorm && dateCheck > bajaNorm) cellValue = 'SC';

      row.push(cellValue);

      // Sumar contadores si no es SC
      if (cellValue !== 'SC') {
        if (cellValue === 'LT') countLT++;
        if (cellValue === 'L') countL++;
        if (cellValue === 'V') countV++;
      }
    }

    // Añadir totales al final de la fila
    row.push(String(countLT), String(countL), String(countV));
    return row;
  });

  return { headers, body, daysInMonth };
};

// Helper para calcular ratios (usado en Excel y PDF)
const calculateRatios = (data: AppData, employees: Employee[], daysInMonth: number) => {
  const { año, mes } = data.metadata;
  const ratios = [];

  for (let d = 1; d <= daysInMonth; d++) {
    let total = 0;
    employees.forEach(emp => {
      const alta = new Date(emp.fechaAlta);
      const baja = emp.fechaBaja ? new Date(emp.fechaBaja) : null;
      const dateCheck = new Date(año, mes - 1, d);

      dateCheck.setHours(0,0,0,0);
      alta.setHours(0,0,0,0);
      if(baja) baja.setHours(0,0,0,0);

      let status = emp.asistencia[String(d)];

      if (dateCheck < alta || (baja && dateCheck > baja)) return;

      const code = CODES.find(c => c.code === status);
      if (code) total += code.ratio;
    });
    ratios.push(total % 1 === 0 ? total : total.toFixed(1));
  }
  return ratios;
};

// Helper para convertir HEX a RGB
const hexToRgb = (hex: string) => {
  const cleanHex = hex.replace('#', '');
  const r = parseInt(cleanHex.substring(0, 2), 16);
  const g = parseInt(cleanHex.substring(2, 4), 16);
  const b = parseInt(cleanHex.substring(4, 6), 16);
  return [r, g, b];
};

// --- EXCEL ---
export const generateExcelReport = (data: AppData, employees: Employee[]) => {
  const { hotel, departamento, año, mes } = data.metadata;
  const monthName = MONTHS[mes - 1];
  const { headers, body, daysInMonth } = prepareDataForReport(data, employees);
  const ratios = calculateRatios(data, employees, daysInMonth);

  // 1. Títulos
  const wsData: any[][] = [
    [`CONTROL DE ASISTENCIA - ${hotel.toUpperCase()}`],
    [`Departamento: ${departamento} | Período: ${monthName} ${año}`],
    [],
    headers,
    ...body
  ];

  // 2. Fila Ratios (Añadir celdas vacías para las 3 columnas de totales)
  const ratioRow = ['RATIO PERSONAL', ...ratios, '', '', ''];
  wsData.push(ratioRow);

  const ws = XLSX.utils.aoa_to_sheet(wsData);

  // Estilos Columnas
  const wscols = [{ wch: 30 }];
  for (let i = 1; i <= daysInMonth; i++) wscols.push({ wch: 4 });
  // Columnas para totales
  wscols.push({ wch: 8 }, { wch: 8 }, { wch: 8 });
  ws['!cols'] = wscols;

  // Leyenda (4 columnas)
  const legendData = [
    ['CÓDIGO', 'DESCRIPCIÓN', 'RATIO', 'TECLA'],
    ...CODES.map(c => [c.code, c.name, c.ratio, c.key.toUpperCase()]),
    ['SC', 'Sin Contrato', 0, '-']
  ];
  const wsLegend = XLSX.utils.aoa_to_sheet(legendData);

  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, "Cuadrante");
  XLSX.utils.book_append_sheet(wb, wsLegend, "Leyenda");

  XLSX.writeFile(wb, `Informe_${hotel.replace(/\s/g, '')}_${departamento}_${monthName}_${año}.xlsx`);
};

// --- PDF ---
export const generatePDFReport = (data: AppData, employees: Employee[]) => {
  const { hotel, departamento, año, mes } = data.metadata;
  const monthName = MONTHS[mes - 1];
  const { headers, body, daysInMonth } = prepareDataForReport(data, employees);

  // Agregar fila de ratios al body
  const ratios = calculateRatios(data, employees, daysInMonth);
  // Añadir huecos vacíos para las columnas de totales
  const ratioRow = ['RATIO PERSONAL', ...ratios, '', '', ''];
  const finalBody = [...body, ratioRow];

  const doc = new jsPDF({ orientation: 'landscape' });

  // Título
  doc.setFontSize(18);
  doc.setTextColor(40);
  doc.text(`CONTROL DE ASISTENCIA - ${hotel}`, 14, 15);
  doc.setFontSize(12);
  doc.setTextColor(100);
  doc.text(`Departamento: ${departamento} | Mes: ${monthName} ${año}`, 14, 22);

  // --- TABLA PRINCIPAL ---
  autoTable(doc, {
    startY: 28,
    head: [headers],
    body: finalBody,
    theme: 'grid',
    styles: { fontSize: 7, cellPadding: 1, halign: 'center', lineColor: [200, 200, 200] },
    headStyles: { fillColor: [21, 101, 192], textColor: 255, fontStyle: 'bold' },
    columnStyles: { 0: { halign: 'left', cellWidth: 40, fontStyle: 'bold' } }, // Nombre más ancho
    didParseCell: (data) => {
      // 1. Estilo para la fila de RATIO (Última fila)
      if (data.section === 'body' && data.row.index === finalBody.length - 1) {
        data.cell.styles.fillColor = [38, 50, 56]; // #263238 (Color web)
        data.cell.styles.textColor = 255;
        data.cell.styles.fontStyle = 'bold';
      }

      // 2. Colorear celdas según código (Solo si no es la fila de ratio y es columna de datos del calendario)
      // data.column.index > 0 (Nombre) y data.column.index <= daysInMonth (Días del mes)
      const isCalendarColumn = data.column.index > 0 && data.column.index <= daysInMonth;

      if (data.section === 'body' && isCalendarColumn && data.row.index < finalBody.length - 1) {
        const codeStr = data.cell.raw as string;
        if (codeStr === 'SC') {
          const rgb = hexToRgb(SC_CODE.bgColor);
          data.cell.styles.fillColor = [rgb[0], rgb[1], rgb[2]];
          const textRgb = hexToRgb(SC_CODE.textColor);
          data.cell.styles.textColor = [textRgb[0], textRgb[1], textRgb[2]];
        } else {
          const code = CODES.find(c => c.code === codeStr);
          if (code) {
            const rgb = hexToRgb(code.bgColor);
            data.cell.styles.fillColor = [rgb[0], rgb[1], rgb[2]];
            data.cell.styles.textColor = code.textColor === '#FFFFFF' ? 255 : 0;
          }
        }
      }

      // 3. Estilo para columnas de resumen (LT, L, V)
      if (data.section === 'head' && data.column.index > daysInMonth) {
        data.cell.styles.fillColor = [224, 224, 224]; // Gris claro cabecera
        data.cell.styles.textColor = 0;
      }
      if (data.section === 'body' && data.column.index > daysInMonth && data.row.index < finalBody.length - 1) {
         data.cell.styles.fontStyle = 'bold';
      }
    }
  });

  // --- LEYENDA (3 Columnas - Sin Ratio) ---
  let finalY = (doc as any).lastAutoTable.finalY || 30;

  // Si queda poco espacio, saltar página
  if (finalY > 150) {
    doc.addPage();
    finalY = 20;
  } else {
    finalY += 10;
  }

  doc.setFontSize(10);
  doc.setTextColor(0);
  doc.text("Leyenda de Códigos:", 14, finalY);

  // Eliminada columna Ratio para PDF
  const legendBody = CODES.map(c => [c.code, c.name, c.key.toUpperCase()]);
  legendBody.push(['SC', 'Sin Contrato', '-']);

  autoTable(doc, {
    startY: finalY + 5,
    head: [['Código', 'Descripción', 'Tecla']],
    body: legendBody,
    theme: 'grid',
    styles: { fontSize: 8, cellPadding: 2, valign: 'middle' },
    headStyles: { fillColor: [66, 66, 66], textColor: 255 },
    columnStyles: {
      0: { halign: 'center', fontStyle: 'bold', cellWidth: 20 },
      1: { cellWidth: 'auto' },
      2: { halign: 'center', cellWidth: 15 }
    },
    // Colorear la primera columna igual que en la web
    didParseCell: (data) => {
      if (data.section === 'body' && data.column.index === 0) {
        const codeStr = data.cell.raw as string;
        let bgColor = '#FFFFFF';
        let textColor = '#000000';

        if (codeStr === 'SC') {
          bgColor = SC_CODE.bgColor;
          textColor = SC_CODE.textColor;
        } else {
          const code = CODES.find(c => c.code === codeStr);
          if (code) {
            bgColor = code.bgColor;
            textColor = code.textColor;
          }
        }

        const bgRgb = hexToRgb(bgColor);
        data.cell.styles.fillColor = [bgRgb[0], bgRgb[1], bgRgb[2]];
        data.cell.styles.textColor = textColor === '#FFFFFF' ? 255 : 0;
      }
    }
  });

  doc.save(`Informe_${hotel.replace(/\s/g, '')}_${departamento}_${monthName}_${año}.pdf`);
};

import React, { useState, useEffect, useCallback, useRef, useMemo } from 'react';
import { AppData, Employee, SelectionState } from '../types';
import { CODES, MONTHS } from '../constants';
import AttendanceGrid from './AttendanceGrid';
import Toolbar from './Toolbar';
import EmployeeModal from './EmployeeModal';
import ManualModal from './ManualModal';
import { saveToStorage, loadFromStorage, loadPreviousMonthData, syncEmployeeAcrossMonths, deleteEmployeeAcrossMonths } from '../services/storageService';
import { generateExcelReport, generatePDFReport } from '../services/reportService';

interface QuadrantScreenProps {
  data: AppData;
  onBack: () => void;
  onUpdateData: (newData: AppData) => void;
}

const QuadrantScreen: React.FC<QuadrantScreenProps> = ({ data, onBack, onUpdateData }) => {
  const [employees, setEmployees] = useState<Employee[]>(data.empleados);
  const [selection, setSelection] = useState<SelectionState>({ start: null, current: null, selectedCells: new Set() });
  const [showEmpModal, setShowEmpModal] = useState(false);
  const [editingEmpId, setEditingEmpId] = useState<string | null>(null);
  const [showManual, setShowManual] = useState(false);
  const [showLegend, setShowLegend] = useState(true);
  const [saveStatus, setSaveStatus] = useState<'saved' | 'saving' | null>(null);
  const [showDownloadMenu, setShowDownloadMenu] = useState(false);
  const downloadMenuRef = useRef<HTMLDivElement>(null);

  // --- Locking Logic ---
  const isMonthLocked = useMemo(() => {
    const { año, mes } = data.metadata;
    // Date(year, monthIndex, 0) gives last day of previous month index.
    const lastDayOfMonth = new Date(año, mes, 0); 

    // Lock date is 7 days after the end of the month
    const lockDate = new Date(lastDayOfMonth);
    lockDate.setDate(lockDate.getDate() + 7);
    lockDate.setHours(23, 59, 59, 999);

    return new Date() > lockDate;
  }, [data.metadata.año, data.metadata.mes]);

  // --- Persistence & Auto-Sync (Local Tab) ---
  useEffect(() => {
    const newData = { ...data, empleados: employees };

    setSaveStatus('saving');
    const timeout = setTimeout(() => {
        saveToStorage(newData);
        setSaveStatus('saved');
        setTimeout(() => setSaveStatus(null), 2000);
    }, 500);

    onUpdateData(newData);

    return () => clearTimeout(timeout);
  }, [employees]);

  // --- Real-time Sync (Cross-Tab) ---
  useEffect(() => {
    const handleStorageChange = (e: StorageEvent) => {
      // Verificar si la clave cambiada corresponde a los datos que estamos viendo
      const currentKey = `asistencia_${data.metadata.hotel.replace(/\s/g, '_')}_${data.metadata.departamento.replace(/\s/g, '_')}_${data.metadata.año}_${data.metadata.mes}`;

      if (e.key === currentKey && e.newValue) {
        try {
          const newData = JSON.parse(e.newValue);
          // Actualizar estado local desde el "servidor" (localStorage)
          setEmployees(newData.empleados);
          onUpdateData(newData);
        } catch (err) {
          console.error("Error syncing from storage event", err);
        }
      }
    };

    window.addEventListener('storage', handleStorageChange);
    return () => window.removeEventListener('storage', handleStorageChange);
  }, [data.metadata]);

  // Click outside to close download menu
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (downloadMenuRef.current && !downloadMenuRef.current.contains(event.target as Node)) {
        setShowDownloadMenu(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // --- Handlers ---

  const handleApplyCode = (code: string) => {
    if (isMonthLocked) return;
    if (selection.selectedCells.size === 0) return;

    setEmployees(prev => prev.map(emp => {
      const newAsistencia = { ...emp.asistencia };
      let modified = false;

      // Iterate 1-31
      for (let d = 1; d <= 31; d++) {
        const key = `${emp.id}_${d}`;
        if (selection.selectedCells.has(key)) {
           newAsistencia[String(d)] = code;
           modified = true;
        }
      }
      return modified ? { ...emp, asistencia: newAsistencia } : emp;
    }));
  };

  const handleKeydown = useCallback((e: KeyboardEvent) => {
    if (showEmpModal || showManual || (e.target as HTMLElement).tagName === 'INPUT') return;
    if (isMonthLocked) return;

    const key = e.key.toLowerCase();
    const found = CODES.find(c => c.key === key);
    if (found) {
      handleApplyCode(found.code);
      e.preventDefault();
    }
  }, [selection, showEmpModal, showManual, isMonthLocked]);

  useEffect(() => {
    window.addEventListener('keydown', handleKeydown);
    return () => window.removeEventListener('keydown', handleKeydown);
  }, [handleKeydown]);

  // --- Selection Logic ---
  const handleCellClick = (empId: string, day: number, ctrlKey: boolean, shiftKey: boolean) => {
    if (isMonthLocked) return;

    const key = `${empId}_${day}`;

    setSelection(prev => {
      const newSet = new Set(ctrlKey ? prev.selectedCells : (shiftKey ? prev.selectedCells : []));

      if (shiftKey && prev.start) {
        const startEmpIdx = employees.findIndex(e => e.id === prev.start!.empId);
        const endEmpIdx = employees.findIndex(e => e.id === empId);
        const startDay = prev.start!.day;
        const endDay = day;

        const minEmp = Math.min(startEmpIdx, endEmpIdx);
        const maxEmp = Math.max(startEmpIdx, endEmpIdx);
        const minDay = Math.min(startDay, endDay);
        const maxDay = Math.max(startDay, endDay);

        for (let i = minEmp; i <= maxEmp; i++) {
          for (let d = minDay; d <= maxDay; d++) {
            newSet.add(`${employees[i].id}_${d}`);
          }
        }
      } else {
        if (ctrlKey && newSet.has(key)) {
          newSet.delete(key);
        } else {
          newSet.add(key);
        }
      }
      const newStart = shiftKey ? prev.start : { empId, day };
      return { start: newStart, current: { empId, day }, selectedCells: newSet };
    });
  };

  // --- Export/Import JSON (Backup) ---
  const handleExport = () => {
    const fileName = `${data.metadata.hotel}_${data.metadata.departamento}_${data.metadata.año}_${String(data.metadata.mes).padStart(2, '0')}.json`.replace(/\s/g, '_');
    const blob = new Blob([JSON.stringify({ ...data, empleados: employees }, null, 2)], { type: 'application/json' });
    const href = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = href;
    link.download = fileName;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (isMonthLocked) {
      alert("No se pueden importar datos en un mes cerrado.");
      return;
    }
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = JSON.parse(event.target?.result as string);
        if (json.metadata && json.empleados) {
          onUpdateData(json);
          setEmployees(json.empleados);
        } else {
          alert('Formato de archivo inválido');
        }
      } catch (err) {
        alert('Error leyendo archivo');
      }
    };
    reader.readAsText(file);
  };

  // --- Import Previous Month Logic ---
  const handleImportPreviousMonth = () => {
    if (isMonthLocked) return;

    const confirmed = window.confirm(
      "¿Estás seguro? Esto reemplazará TODOS los datos actuales con la copia del mes anterior. Se perderán los datos no guardados de este mes."
    );

    if (!confirmed) return;

    const prevData = loadPreviousMonthData(
      data.metadata.hotel, 
      data.metadata.departamento, 
      data.metadata.año, 
      data.metadata.mes
    );

    if (!prevData || prevData.empleados.length === 0) {
      alert("No se encontraron datos en el mes anterior para importar.");
      return;
    }

    // Reemplazamos completamente los empleados actuales con los del mes anterior
    // Incluyendo su asistencia
    const importedEmployees = prevData.empleados.map(emp => ({
      ...emp,
      asistencia: { ...emp.asistencia } // Clonamos la asistencia para evitar referencias compartidas
    }));

    setEmployees(importedEmployees);
    alert("Cuadrante del mes anterior importado exitosamente.");
  };

  // --- Employee CRUD (Replicated) ---
  const handleSaveEmployee = (emp: Employee) => {
    // 1. Update Local State (Current Month)
    if (employees.find(e => e.id === emp.id)) {
      setEmployees(prev => prev.map(e => e.id === emp.id ? emp : e));
    } else {
      setEmployees(prev => [...prev, emp]);
    }

    // 2. Replicate to "Server" (All Months)
    // Esto asegura que si editamos el nombre o fechas, se actualiza en el historial
    // y si creamos uno nuevo, se añade a otros meses existentes.
    syncEmployeeAcrossMonths(data.metadata.hotel, data.metadata.departamento, emp);
  };

  const handleDeleteEmployee = (id: string) => {
    // 1. Update Local State
    setEmployees(prev => prev.filter(e => e.id !== id));

    // 2. Replicate to "Server" (All Months)
    deleteEmployeeAcrossMonths(data.metadata.hotel, data.metadata.departamento, id);
  };

  return (
    <div className="flex flex-col h-screen bg-gray-50 text-gray-900">

      {/* Header */}
      <header className="bg-white shadow z-30 px-4 py-2 flex justify-between items-center border-b border-gray-200">
        <div className="flex items-center gap-4">
          <button onClick={onBack} className="text-gray-600 hover:text-blue-600 font-bold flex items-center gap-1">
            ← Volver
          </button>
          <div className="text-sm">
            <span className="font-bold text-gray-800">{data.metadata.hotel}</span>
            <span className="mx-2 text-gray-400">|</span>
            <span className="text-blue-600 font-medium">{data.metadata.departamento}</span>
            <span className="mx-2 text-gray-400">|</span>
            <span className="text-gray-600">{MONTHS[data.metadata.mes - 1]} {data.metadata.año}</span>
          </div>
        </div>

        <div className="flex items-center gap-2">
          {/* Download Dropdown */}
          <div className="relative" ref={downloadMenuRef}>
            <button 
              onClick={() => setShowDownloadMenu(!showDownloadMenu)}
              className="flex items-center gap-1 px-3 py-1 bg-green-100 text-green-800 rounded hover:bg-green-200 text-sm font-medium transition-colors"
            >
              📥 Descargar Informe ▼
            </button>
            {showDownloadMenu && (
              <div className="absolute right-0 mt-2 w-48 bg-white rounded-md shadow-lg py-1 z-50 border border-gray-200">
                <button 
                  onClick={() => { generatePDFReport(data, employees); setShowDownloadMenu(false); }}
                  className="block px-4 py-2 text-sm text-gray-700 hover:bg-gray-100 w-full text-left flex items-center gap-2"
                >
                  📄 Formato PDF (Horizontal)
                </button>
                <button 
                  onClick={() => { generateExcelReport(data, employees); setShowDownloadMenu(false); }}
                  className="block px-4 py-2 text-sm text-gray-700 hover:bg-gray-100 w-full text-left flex items-center gap-2"
                >
                  📊 Formato Excel (.xlsx)
                </button>
              </div>
            )}
          </div>

          <button 
            onClick={handleImportPreviousMonth}
            className={`px-3 py-1 rounded text-sm font-medium flex items-center gap-1 ${isMonthLocked ? 'bg-gray-200 text-gray-400 cursor-not-allowed' : 'bg-orange-50 text-orange-700 hover:bg-orange-100'}`}
            disabled={isMonthLocked}
            title="Copia la asistencia del mes anterior"
          >
            🗓️ Importar mes anterior
          </button>

          <div className="h-6 w-px bg-gray-300 mx-1"></div>

          <button 
            onClick={() => { setEditingEmpId(null); setShowEmpModal(true); }} 
            className={`px-3 py-1 rounded text-sm font-medium ${isMonthLocked ? 'bg-gray-200 text-gray-400 cursor-not-allowed' : 'bg-blue-50 text-blue-700 hover:bg-blue-100'}`}
            disabled={isMonthLocked}
            title={isMonthLocked ? 'Mes cerrado' : 'Gestionar Empleados'}
          >
            👤 Empleados
          </button>
          <button 
            onClick={handleExport} 
            className="px-3 py-1 bg-gray-100 text-gray-700 rounded hover:bg-gray-200 text-sm font-medium"
          >
            💾 Backup JSON
          </button>
          <label className={`px-3 py-1 bg-gray-100 text-gray-700 rounded text-sm font-medium ${isMonthLocked ? 'cursor-not-allowed opacity-50' : 'cursor-pointer hover:bg-gray-200'}`}>
            📂 Restaurar JSON
            <input type="file" className="hidden" accept=".json" onChange={handleImport} disabled={isMonthLocked} />
          </label>
          <button onClick={() => setShowManual(true)} className="px-3 py-1 bg-yellow-50 text-yellow-700 rounded hover:bg-yellow-100 text-sm font-medium">
            ❓ Ayuda
          </button>
        </div>
      </header>

      {/* Locked Month Banner */}
      {isMonthLocked && (
        <div className="bg-red-500 text-white text-center py-2 px-4 text-sm font-bold shadow-md z-40">
          🔒 ESTE MES ESTÁ CERRADO. Solo lectura permitida.
        </div>
      )}

      {/* Legend Toggle */}
      <div className="bg-white border-b border-gray-100 px-4 py-1">
        <button 
          onClick={() => setShowLegend(!showLegend)} 
          className="text-xs text-gray-500 hover:text-blue-600 flex items-center gap-1 w-full"
        >
          {showLegend ? '▼ Ocultar Leyenda' : '▶ Mostrar Leyenda'}
        </button>
      </div>

      {/* Legend */}
      {showLegend && (
        <div className="bg-white p-3 border-b border-gray-200 grid grid-cols-2 md:grid-cols-4 lg:grid-cols-7 gap-2 text-xs overflow-y-auto max-h-32">
          {CODES.map(c => (
            <div key={c.code} className="flex items-center gap-2">
              <span className="w-6 h-6 flex items-center justify-center font-bold rounded border shadow-sm" style={{ backgroundColor: c.bgColor, color: c.textColor }}>
                {c.code}
              </span>
              <span className="truncate" title={c.name}>{c.name} <span className="text-gray-400">({c.key.toUpperCase()})</span></span>
            </div>
          ))}
        </div>
      )}

      {/* Main Toolbar */}
      <Toolbar onApplyCode={handleApplyCode} readOnly={isMonthLocked} />

      {/* Grid Area */}
      <div className="flex-1 overflow-hidden relative">
        <AttendanceGrid 
          year={data.metadata.año}
          month={data.metadata.mes}
          employees={employees}
          selection={selection}
          setSelection={setSelection}
          onCellClick={handleCellClick}
          onEditEmployee={(id) => { 
            if (!isMonthLocked) {
              setEditingEmpId(id); 
              setShowEmpModal(true);
            }
          }}
          readOnly={isMonthLocked}
        />

        {/* Status Toast */}
        {saveStatus === 'saving' && (
          <div className="absolute bottom-10 right-10 bg-blue-600/90 text-white px-4 py-2 rounded-full text-sm font-medium flex items-center gap-2 shadow-lg z-50">
            <span className="animate-spin h-3 w-3 border-2 border-white border-t-transparent rounded-full"></span>
            Sincronizando...
          </div>
        )}
        {saveStatus === 'saved' && (
          <div className="absolute bottom-10 right-10 bg-green-600/90 text-white px-4 py-2 rounded-full text-sm font-medium shadow-lg z-50">
            ✓ Guardado en servidor
          </div>
        )}
      </div>

      {/* Modals */}
      <EmployeeModal 
        isOpen={showEmpModal} 
        onClose={() => setShowEmpModal(false)}
        employees={employees}
        editId={editingEmpId}
        onSave={handleSaveEmployee}
        onDelete={handleDeleteEmployee}
        onReorder={setEmployees}
      />

      <ManualModal isOpen={showManual} onClose={() => setShowManual(false)} />

    </div>
  );
};

export default QuadrantScreen;

export interface AttendanceCode {
  code: string;
  name: string;
  bgColor: string;
  textColor: string;
  ratio: number;
  key: string;
}

export interface PeriodoPrueba {
  activo: boolean;
  dias: number;
  fechaFin: string | null;
}

export interface Employee {
  id: string;
  nombre: string;
  fechaAlta: string;
  fechaBaja: string | null;
  periodoPrueba: PeriodoPrueba;
  asistencia: Record<string, string>; // key is day number (1-31)
  horasExtras: Record<string, number>; // key is day number, value is hours
}

export interface AppMetadata {
  hotel: string;
  departamento: string;
  año: number;
  mes: number;
  ultimaModificacion: string;
}

export interface AppData {
  metadata: AppMetadata;
  empleados: Employee[];
}

export interface SelectionState {
  start: { empId: string; day: number } | null;
  current: { empId: string; day: number } | null;
  selectedCells: Set<string>; // Format: "empId_day"
}

export interface DragState {
