      } else {
        reject(new Error("sql.js script loaded but initSqlJs is not defined."));
      }
    };

    script.onerror = () => {
      reject(new Error("Failed to load sql.js from CDN. Please check your internet connection or ad blockers."));
    };

    document.head.appendChild(script);
  });
};

