interface QuadrantScreenProps {
  data: AppData;
  onBack: () => void;
  onUpdateData: (newData: AppData) => void;
  onChangeMonth: (year: number, month: number) => void;
}

const QuadrantScreen: React.FC<QuadrantScreenProps> = ({ data, onBack, onUpdateData, onChangeMonth }) => {
  // Initialize with props, but update when props change (CRITICAL FIX)
  const [employees, setEmployees] = useState<Employee[]>(data.empleados);
  const [selection, setSelection] = useState<SelectionState>({ start: null, current: null, selectedCells: new Set() });
  const [showEmpModal, setShowEmpModal] = useState(false);
  const [editingEmpId, setEditingEmpId] = useState<string | null>(null);
  const [showManual, setShowManual] = useState(false);
  const [showLegend, setShowLegend] = useState(true);
  const [saveStatus, setSaveStatus] = useState<'saved' | 'saving' | null>(null);
  const [showDownloadMenu, setShowDownloadMenu] = useState(false);
  const [heModal, setHeModal] = useState<{ open: boolean; empId: string; day: number; val: number }>({ open: false, empId: '', day: 0, val: 0 });

  const downloadMenuRef = useRef<HTMLDivElement>(null);

  // Sync state with props when month changes
  useEffect(() => {
    setEmployees(data.empleados);
    setSelection({ start: null, current: null, selectedCells: new Set() });
  }, [data]);

  const isMonthLocked = useMemo(() => {
    const { año, mes } = data.metadata;
    const lastDayOfMonth = new Date(año, mes, 0); 
    const lockDate = new Date(lastDayOfMonth);
    lockDate.setDate(lockDate.getDate() + 7);
    lockDate.setHours(23, 59, 59, 999);
    return new Date() > lockDate;
  }, [data.metadata.año, data.metadata.mes]);

  // Auto-save effect
  useEffect(() => {
    // Avoid saving if employees matches data.empleados exactly (prevents loop on initial load)
    if (JSON.stringify(employees) === JSON.stringify(data.empleados)) return;

    const newData = { ...data, empleados: employees };
    setSaveStatus('saving');

    const timeout = setTimeout(async () => {
        await saveToStorage(newData);
        setSaveStatus('saved');
        onUpdateData(newData); // Update parent state to keep sync
        setTimeout(() => setSaveStatus(null), 2000);
    }, 800);

    return () => clearTimeout(timeout);
  }, [employees]); // Dependency on employees

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (downloadMenuRef.current && !downloadMenuRef.current.contains(event.target as Node)) {
        setShowDownloadMenu(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleApplyCode = (code: string) => {
    if (isMonthLocked) return;
    if (selection.selectedCells.size === 0) return;
    setEmployees(prev => prev.map(emp => {
      const newAsistencia = { ...emp.asistencia };
      let modified = false;
      for (let d = 1; d <= 31; d++) {
        if (selection.selectedCells.has(`${emp.id}_${d}`)) {
           newAsistencia[String(d)] = code;
           modified = true;
        }
      }
      return modified ? { ...emp, asistencia: newAsistencia } : emp;
    }));
  };

  const handleKeydown = useCallback((e: KeyboardEvent) => {
    if (showEmpModal || showManual || heModal.open || (e.target as HTMLElement).tagName === 'INPUT') return;
    if (isMonthLocked) return;
    const found = CODES.find(c => c.key === e.key.toLowerCase());
    if (found) { handleApplyCode(found.code); e.preventDefault(); }
  }, [selection, showEmpModal, showManual, isMonthLocked, heModal.open]);

  useEffect(() => {
    window.addEventListener('keydown', handleKeydown);
    return () => window.removeEventListener('keydown', handleKeydown);
  }, [handleKeydown]);

  const handleCellClick = (empId: string, day: number, ctrlKey: boolean, shiftKey: boolean) => {
    if (isMonthLocked) return;
    setSelection(prev => {
      const newSet = new Set(ctrlKey ? prev.selectedCells : (shiftKey ? prev.selectedCells : []));
      if (shiftKey && prev.start) {
        const startEmpIdx = employees.findIndex(e => e.id === prev.start!.empId);
        const endEmpIdx = employees.findIndex(e => e.id === empId);
        const minEmp = Math.min(startEmpIdx, endEmpIdx), maxEmp = Math.max(startEmpIdx, endEmpIdx);
        const minDay = Math.min(prev.start!.day, day), maxDay = Math.max(prev.start!.day, day);
        for (let i = minEmp; i <= maxEmp; i++) for (let d = minDay; d <= maxDay; d++) newSet.add(`${employees[i].id}_${d}`);
      } else {
        const key = `${empId}_${day}`;
        if (ctrlKey && newSet.has(key)) newSet.delete(key); else newSet.add(key);
      }
      return { start: shiftKey ? prev.start : { empId, day }, current: { empId, day }, selectedCells: newSet };
    });
  };

  const handleCellDoubleClick = (empId: string, day: number) => {
    if (isMonthLocked) return;
    const emp = employees.find(e => e.id === empId);
    if (emp) setHeModal({ open: true, empId, day, val: emp.horasExtras?.[String(day)] || 0 });
  };

  const handleSaveHE = (hours: number) => {
    setEmployees(prev => prev.map(e => {
      if (e.id === heModal.empId) {
        const newHE = { ...e.horasExtras, [String(heModal.day)]: hours };
        return { ...e, horasExtras: newHE };
      }
      return e;
    }));
    setHeModal({ ...heModal, open: false });
  };

  const handleImportPreviousMonth = async () => {
    if (isMonthLocked) return;
    if (!window.confirm("¿Estás seguro de copiar los datos del mes anterior?\nSe sobrescribirán la asistencia y empleados actuales.")) return;

    try {
      setSaveStatus('saving');
      const prevData = await loadPreviousMonthData(data.metadata.hotel, data.metadata.departamento, data.metadata.año, data.metadata.mes);

      if (!prevData || prevData.empleados.length === 0) { 
        alert("No se encontraron datos en el mes anterior.");
        setSaveStatus(null);
        return; 
      }

      // Copy employees AND their attendance/HE from previous month
      const newEmployees = prevData.empleados.map(e => ({
        ...e,
        asistencia: { ...e.asistencia },
        horasExtras: { ...e.horasExtras }
      }));

      setEmployees(newEmployees);

      // Force immediate save and update parent
      const newData = { ...data, empleados: newEmployees };
      await saveToStorage(newData);
      onUpdateData(newData);

      setSaveStatus('saved');
      setTimeout(() => setSaveStatus(null), 2000);

    } catch (e) {
      console.error(e);
      alert("Error al importar datos.");
      setSaveStatus(null);
    }
  };

  const handleSaveEmployee = async (emp: Employee) => {
    setEmployees(prev => prev.find(e => e.id === emp.id) ? prev.map(e => e.id === emp.id ? emp : e) : [...prev, emp]);
    await syncEmployeeAcrossMonths(data.metadata.hotel, data.metadata.departamento, emp);
  };

  const handleDeleteEmployee = async (id: string) => {
    setEmployees(prev => prev.filter(e => e.id !== id));
    await deleteEmployeeAcrossMonths(data.metadata.hotel, data.metadata.departamento, id);
  };

  return (
    <div className="flex flex-col h-screen bg-gray-50 text-gray-900">
      <header className="bg-white shadow z-30 px-4 py-2 flex justify-between items-center border-b border-gray-200">
        <div className="flex items-center gap-4">
          <button onClick={onBack} className="text-gray-600 hover:text-blue-600 font-bold flex items-center gap-1">
            <span>←</span> Volver
          </button>

          <div className="flex items-center bg-gray-100 rounded-lg p-1 border border-gray-200">
            <button 
              onClick={() => onChangeMonth(data.metadata.año, data.metadata.mes - 1)}
              className="px-3 py-1 hover:bg-white hover:shadow rounded text-gray-600 font-bold"
              title="Mes Anterior"
            >
              &lt;
            </button>
            <div className="text-sm px-4 text-center min-w-[180px]">
              <div className="font-bold text-gray-800 leading-tight">{data.metadata.hotel}</div>
              <div className="text-xs text-gray-500">
                <span className="text-blue-600 font-medium">{data.metadata.departamento}</span>
                <span className="mx-2">|</span>
                <span className="uppercase font-bold">{MONTHS[data.metadata.mes - 1]} {data.metadata.año}</span>
              </div>
            </div>
            <button 
               onClick={() => onChangeMonth(data.metadata.año, data.metadata.mes + 1)}
               className="px-3 py-1 hover:bg-white hover:shadow rounded text-gray-600 font-bold"
               title="Mes Siguiente"
            >
              &gt;
            </button>
          </div>
        </div>

        <div className="flex items-center gap-2">
          <div className="relative" ref={downloadMenuRef}>
            <button onClick={() => setShowDownloadMenu(!showDownloadMenu)} className="px-3 py-1 bg-green-100 text-green-800 rounded text-sm font-medium hover:bg-green-200 transition-colors">📥 Informe ▼</button>
            {showDownloadMenu && (
              <div className="absolute right-0 mt-2 w-48 bg-white rounded shadow-lg py-1 z-50 border ring-1 ring-black ring-opacity-5">
                <button onClick={() => { generatePDFReport(data, employees); setShowDownloadMenu(false); }} className="block px-4 py-2 text-sm text-gray-700 hover:bg-gray-100 w-full text-left">📄 PDF (Imprimir)</button>
                <button onClick={() => { generateExcelReport(data, employees); setShowDownloadMenu(false); }} className="block px-4 py-2 text-sm text-gray-700 hover:bg-gray-100 w-full text-left">📊 Excel (Editable)</button>
              </div>
            )}
          </div>

          <button 
            onClick={handleImportPreviousMonth} 
            disabled={isMonthLocked} 
            title="Copiar datos del mes anterior"
            className={`px-3 py-1 rounded text-sm font-medium flex items-center gap-1 transition-colors ${isMonthLocked ? 'bg-gray-200 text-gray-400 cursor-not-allowed' : 'bg-orange-50 text-orange-700 hover:bg-orange-100'}`}
          >
            <span>📅</span> Importar mes anterior
          </button>

          <button 
            onClick={() => { setEditingEmpId(null); setShowEmpModal(true); }} 
            disabled={isMonthLocked} 
            className={`px-3 py-1 rounded text-sm font-medium flex items-center gap-1 transition-colors ${isMonthLocked ? 'bg-gray-200 text-gray-400 cursor-not-allowed' : 'bg-blue-50 text-blue-700 hover:bg-blue-100'}`}
          >
            <span>👤</span> Empleados
          </button>

          <button onClick={() => setShowManual(true)} className="px-3 py-1 bg-yellow-50 text-yellow-700 rounded text-sm font-medium hover:bg-yellow-100 transition-colors">❓</button>
        </div>
      </header>

      {isMonthLocked && <div className="bg-red-600 text-white text-center py-1 text-xs font-bold uppercase tracking-wider">🔒 Este mes está cerrado - Solo lectura</div>}

      {showLegend && (
        <div className="bg-white p-2 border-b grid grid-cols-4 md:grid-cols-7 gap-2 text-[10px] max-h-24 overflow-auto">
          {CODES.map(c => (
            <div key={c.code} className="flex items-center gap-1">
              <span className="w-5 h-5 flex items-center justify-center font-bold rounded shadow-sm text-[10px]" style={{ backgroundColor: c.bgColor, color: c.textColor }}>{c.code}</span>
              <span className="truncate text-gray-600">{c.name}</span>
            </div>
          ))}
          <div className="flex items-center gap-1"><span className="w-5 h-5 bg-orange-600 text-white flex items-center justify-center rounded font-bold text-[10px]">HE</span><span className="text-gray-600">Horas Extras</span></div>
        </div>
      )}

      <Toolbar onApplyCode={handleApplyCode} readOnly={isMonthLocked} />

      <div className="flex-1 overflow-hidden relative">
        <AttendanceGrid 
          year={data.metadata.año} month={data.metadata.mes} employees={employees}
          selection={selection} setSelection={setSelection} onCellClick={handleCellClick}
          onCellDoubleClick={handleCellDoubleClick} onEditEmployee={(id) => { if(!isMonthLocked){ setEditingEmpId(id); setShowEmpModal(true); } }}
          readOnly={isMonthLocked}
        />
        {saveStatus && (
          <div className={`absolute bottom-6 right-6 px-4 py-2 rounded-lg text-sm font-medium shadow-xl z-50 flex items-center gap-2 transition-all duration-300 ${saveStatus === 'saving' ? 'bg-blue-600 text-white' : 'bg-green-600 text-white'}`}>
             {saveStatus === 'saving' ? (
               <>
                <div className="animate-spin h-3 w-3 border-2 border-white border-t-transparent rounded-full"></div>
                Guardando...
               </>
             ) : (
               <>
                <span>✓</span> Guardado
               </>
             )}
          </div>
        )}
      </div>

      <EmployeeModal isOpen={showEmpModal} onClose={() => setShowEmpModal(false)} employees={employees} editId={editingEmpId} onSave={handleSaveEmployee} onDelete={handleDeleteEmployee} onReorder={setEmployees} />
      <ExtraHoursModal isOpen={heModal.open} onClose={() => setHeModal({ ...heModal, open: false })} onSave={handleSaveHE} currentHours={heModal.val} empName={employees.find(e => e.id === heModal.empId)?.nombre || ''} day={heModal.day} />
      <ManualModal isOpen={showManual} onClose={() => setShowManual(false)} />
    </div>
  );
};

export default QuadrantScreen;

import localforage from 'localforage';
import { AppData, Employee, User } from '../types';

let db: any = null;
const DB_NAME = 'hotel_attendance_db';

const CDN_URLS = [
  "https://cdnjs.cloudflare.com/ajax/libs/sql.js/1.12.0/dist/",
  "https://unpkg.com/sql.js@1.12.0/dist/"
];

// Helper to dynamically load the SQL.js script with fallback
const loadSqlJsLib = async (): Promise<{ initSqlJs: any, baseUrl: string }> => {
  if ((window as any).initSqlJs) {
    return { initSqlJs: (window as any).initSqlJs, baseUrl: CDN_URLS[0] };
  }

  for (const baseUrl of CDN_URLS) {
    try {
      await new Promise<void>((resolve, reject) => {
        const script = document.createElement('script');
        script.src = `${baseUrl}sql-wasm.js`;
        script.async = true;

        script.onload = () => {
          if ((window as any).initSqlJs) {
            resolve();
          } else {
            reject(new Error("Script loaded but initSqlJs is not defined."));
          }
        };

        script.onerror = () => {
          reject(new Error(`Failed to load script from ${baseUrl}`));
        };

        document.head.appendChild(script);
      });

      console.log(`Successfully loaded sql.js from ${baseUrl}`);
      return { initSqlJs: (window as any).initSqlJs, baseUrl };
    } catch (error) {
      console.warn(`Attempt to load sql.js from ${baseUrl} failed. Trying next source...`);
    }
  }

  throw new Error("CRITICAL: sql.js library could not be loaded from any CDN. Please check your internet connection.");
};

export const initDB = async () => {
  if (db) return db;

  try {
    const { initSqlJs, baseUrl } = await loadSqlJsLib();

    const SQL = await initSqlJs({
      locateFile: (file: string) => `${baseUrl}${file}`
    });

    const savedDb: ArrayBuffer | null = await localforage.getItem(DB_NAME);

    if (savedDb) {
      db = new SQL.Database(new Uint8Array(savedDb));
    } else {
      db = new SQL.Database();
    }

    // Schema definition - Always run to ensure new tables/columns are added to existing DBs
    db.run(`
      CREATE TABLE IF NOT EXISTS metadata (
        hotel TEXT,
        departamento TEXT,
        año INTEGER,
        mes INTEGER,
        ultimaModificacion TEXT,
        PRIMARY KEY (hotel, departamento, año, mes)
      );
      CREATE TABLE IF NOT EXISTS employees (
        id TEXT PRIMARY KEY,
        hotel TEXT,
        departamento TEXT,
        nombre TEXT,
        fechaAlta TEXT,
        fechaBaja TEXT,
        trial_active INTEGER,
        trial_dias INTEGER,
        trial_fechaFin TEXT
      );
      CREATE TABLE IF NOT EXISTS attendance (
        employee_id TEXT,
        año INTEGER,
        mes INTEGER,
        dia INTEGER,
        code TEXT,
        horas_extras REAL,
        PRIMARY KEY (employee_id, año, mes, dia)
      );
      CREATE TABLE IF NOT EXISTS users (
        username TEXT PRIMARY KEY,
        password TEXT,
        role TEXT,
        allowed_departments TEXT
      );
    `);

    await persistDB();
    await seedUsers();

    return db;
  } catch (error) {
    console.error("Database initialization failed:", error);
    throw error;
  }
};

const seedUsers = async () => {
  if (!db) return;
  db.run(`INSERT OR IGNORE INTO users (username, password, role, allowed_departments) VALUES (?, ?, ?, ?)`,
    ['admin', '1579@Chemas', 'admin', '["ALL"]']);
  db.run(`INSERT OR IGNORE INTO users (username, password, role, allowed_departments) VALUES (?, ?, ?, ?)`,
    ['cocina', 'cocina', 'user', '["Cocina"]']);
  await persistDB();
};

const persistDB = async () => {
  if (!db) return;
  const binaryDb = db.export();
  await localforage.setItem(DB_NAME, binaryDb.buffer);
};

// --- USER MANAGEMENT ---

export const loginUser = async (username: string, password: string): Promise<User | null> => {
  await initDB();
  const res = db.exec(`SELECT * FROM users WHERE username = ? AND password = ?`, [username, password]);
  if (res.length > 0 && res[0].values.length > 0) {
    const row = res[0].values[0];
    return {
      username: row[0] as string,
      role: row[2] as 'admin' | 'user',
      allowedDepartments: JSON.parse(row[3] as string)
    };
  }
  return null;
};

export const getAllUsers = async (): Promise<User[]> => {
  await initDB();
  const res = db.exec(`SELECT username, role, allowed_departments FROM users`);
  if (res.length === 0) return [];
  return res[0].values.map((row: any) => ({
    username: row[0],
    role: row[1],
    allowedDepartments: JSON.parse(row[2])
  }));
};

export const saveUser = async (user: User, password?: string) => {
  await initDB();
  if (password) {
    db.run(`INSERT OR REPLACE INTO users (username, password, role, allowed_departments) VALUES (?, ?, ?, ?)`,
      [user.username, password, user.role, JSON.stringify(user.allowedDepartments)]);
  } else {
    const oldRes = db.exec(`SELECT password FROM users WHERE username = ?`, [user.username]);
    const oldPass = oldRes.length > 0 ? oldRes[0].values[0][0] : '123456'; 
    db.run(`INSERT OR REPLACE INTO users (username, password, role, allowed_departments) VALUES (?, ?, ?, ?)`,
      [user.username, oldPass, user.role, JSON.stringify(user.allowedDepartments)]);
  }
  await persistDB();
};

export const deleteUser = async (username: string) => {
  await initDB();
  db.run(`DELETE FROM users WHERE username = ?`, [username]);
  await persistDB();
};

// --- APP DATA ---

export const saveToStorage = async (data: AppData) => {
  if (!db) await initDB();

  const { hotel, departamento, año, mes } = data.metadata;
  const modDate = new Date().toISOString();

  // Save Metadata
  db.run(`INSERT OR REPLACE INTO metadata VALUES (?, ?, ?, ?, ?)`, 
    [hotel, departamento, año, mes, modDate]);

  // Save Employees and Attendance
  for (const emp of data.empleados) {
    db.run(`INSERT OR REPLACE INTO employees VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`, [
      emp.id, hotel, departamento, emp.nombre, emp.fechaAlta, emp.fechaBaja,
      emp.periodoPrueba.activo ? 1 : 0, emp.periodoPrueba.dias, emp.periodoPrueba.fechaFin
    ]);

    db.run(`DELETE FROM attendance WHERE employee_id = ? AND año = ? AND mes = ?`, [emp.id, año, mes]);

    for (const day in emp.asistencia) {
      const code = emp.asistencia[day];
      const he = emp.horasExtras[day] || 0;
      if (code || he > 0) {
        db.run(`INSERT INTO attendance VALUES (?, ?, ?, ?, ?, ?)`, 
          [emp.id, año, mes, parseInt(day), code, he]);
      }
    }
  }
  await persistDB();
};

export const loadFromStorage = async (hotel: string, dept: string, año: number, mes: number): Promise<AppData | null> => {
  await initDB();

  // Try finding metadata, but don't hard fail if missing if employees exist
  const meta = db.exec(`SELECT * FROM metadata WHERE hotel=? AND departamento=? AND año=? AND mes=?`, [hotel, dept, año, mes]);

  const employeesResult = db.exec(`SELECT * FROM employees WHERE hotel=? AND departamento=?`, [hotel, dept]);

  // If absolutely nothing exists for this context
  if (employeesResult.length === 0 && meta.length === 0) return null;

  const employees: Employee[] = [];

  if (employeesResult.length > 0) {
    const rows = employeesResult[0].values;
    for (const row of rows) {
      const empId = row[0] as string;

      const attendanceResult = db.exec(`SELECT dia, code, horas_extras FROM attendance WHERE employee_id=? AND año=? AND mes=?`, [empId, año, mes]);
      const asistencia: Record<string, string> = {};
      const horasExtras: Record<string, number> = {};

      if (attendanceResult.length > 0) {
        attendanceResult[0].values.forEach((attRow: any) => {
          asistencia[String(attRow[0])] = attRow[1];
          if (attRow[2]) horasExtras[String(attRow[0])] = attRow[2];
        });
      }

      employees.push({
        id: empId,
        nombre: row[3] as string,
        fechaAlta: row[4] as string,
        fechaBaja: row[5] as string || null,
        periodoPrueba: {
          activo: row[6] === 1,
          dias: row[7] as number,
          fechaFin: row[8] as string || null
        },
        asistencia,
        horasExtras
      });
    }
  }

  const lastMod = meta.length > 0 ? meta[0].values[0][4] : new Date().toISOString();

  return {
    metadata: {
      hotel,
      departamento: dept,
      año,
      mes,
      ultimaModificacion: lastMod
    },
    empleados: employees
  };
};

export const findRecentEmployees = async (hotel: string, dept: string): Promise<Employee[]> => {
  await initDB();
  const employeesResult = db.exec(`SELECT * FROM employees WHERE hotel=? AND departamento=?`, [hotel, dept]);
  if (employeesResult.length === 0) return [];

  return employeesResult[0].values.map((row: any) => ({
    id: row[0],
    nombre: row[3],
    fechaAlta: row[4],
    fechaBaja: row[5],
    periodoPrueba: { activo: row[6] === 1, dias: row[7], fechaFin: row[8] },
    asistencia: {},
    horasExtras: {}
  }));
};

export const syncEmployeeAcrossMonths = async (hotel: string, dept: string, employee: Employee) => {
  await initDB();
  db.run(`INSERT OR REPLACE INTO employees VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`, [
    employee.id, hotel, dept, employee.nombre, employee.fechaAlta, employee.fechaBaja,
    employee.periodoPrueba.activo ? 1 : 0, employee.periodoPrueba.dias, employee.periodoPrueba.fechaFin
  ]);
  await persistDB();
};

export const deleteEmployeeAcrossMonths = async (hotel: string, dept: string, employeeId: string) => {
  await initDB();
  db.run(`DELETE FROM employees WHERE id = ?`, [employeeId]);
  db.run(`DELETE FROM attendance WHERE employee_id = ?`, [employeeId]);
  await persistDB();
};

export const loadPreviousMonthData = async (hotel: string, dept: string, currentYear: number, currentMonth: number): Promise<AppData | null> => {
  let prevMonth = currentMonth - 1;
  let prevYear = currentYear;
  if (prevMonth === 0) { prevMonth = 12; prevYear = currentYear - 1; }
  return loadFromStorage(hotel, dept, prevYear, prevMonth);
};

